INSERT INTO `package_itinerary` (`id`, `package_id`, `day_number`, `title`, `description`, `meals`, `accommodation`, `activities`, `display_order`, `created_at`) VALUES
(160, 6, 1, 'Pick up from Delhi airport transfer to Haridwar.', 'Highlights - Ganga Aarati at Har ki Pauri\r\n\r\nMeet our assistance on arrival as per your predefined schedule and further proceed to Haridwar.\r\nUpon arrival check into the hotel and further you can proceed for Ganga Aarti at Har Ki Pouri on\r\nyour own if possible with available time and conditions. So here Har Ki pouri is the center point\r\nof Haridwar and there are several local transports available for this sight. We kept you free to\r\nexplore the local Haridwar and edge of Ganges. Overnight stay in Haridwar.', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(161, 6, 2, 'Haridwar Barkot (approx 215km / 07 hrs. drive)', 'Highlights - Mussoorie & Kempty Fall\r\n\r\nThis morning, you depart for Barkot. Barkot is a beautiful hill station which is located on the foot\r\nof Yamunotri. As you drive through Mussoorie, you can visit the famous Kempty Falls on your\r\nway. On arrival at Barkot, check-in to your hotel/camp. Rest of the day is free to relax and store\r\nyour energy for the hiII Yatra of Yamunotri Overnight stay at Barkot.', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(162, 6, 3, 'Barkot  Yamunotri Barkot (approx 42 km DRIVE / 06 km TREK)', 'Highlights - Yamunotri Temple\r\n\r\nAfter breakfast, depart for Hanumanchatti (40 Km), Janki Chatti (8 km). Here you will begin the\r\nFirst hill Yatra of Yamunotri (6 Km trek). You have an option of hiring Palki or a horse for your\r\ntrek. (Cost Not Included).\r\nThe trek passes through lush green valley, a profusion of conifers, rhododendrons, cacti and\r\nseveral species of Himalayan shrubs.', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(163, 6, 4, 'Barkot  Uttarkashi (approx DRIVE 82 km, / 04 hrs. DRIVE)', 'Highlights - Vishwanath Temple\r\n\r\nAfter breakfast check out from the Barkot hotel and drive to Uttarkashi. En route visit the famous\r\nVishwanath Temple on Uttarkashi. On arrival check in into the hotel. Uttarkashi is situated on the\r\nbanks of river Bhagirathi and is famous for its historical monuments, Temples & Ashrams. .\r\nOvernight stay at Uttarkashi.', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(164, 6, 5, 'Uttarkashi  Gangotri Uttarkashi (approx 100 km. PER WAY)', 'Highlights - Gangotri Temple\r\n\r\nEarly morning breakfast at the hotel and drive to Gangotri. Upon arrival at Gangotri take a holy\r\ndip in the sacred river Ganges which is also called Bhagirathi at its origin. Visit the Gangotri\r\nTemple. The 18th century\'s temple dedicated to Goddess Ganga is located near a sacred stone\r\nwhere King Bhagirathi worshiped Lord Shiva. Ganga is believed to have touched earth at this\r\nspot. The temple is an exquisite 20 ft. high structure made of white granite. After performing\r\nPooja, afternoon drive back to Uttarkashi. Overnight stay at Uttarkashi.', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(165, 6, 6, 'Uttarkashi  Guptkashi / Phata (approx 223 kms / 09 hrs DRIVE)', 'Highlights - Shree Kashi Vishwanath Temple and Ardhnareshwar Temple\r\n\r\nLeave for your next destination, Guptkashi after having your breakfast early in the morning. On\r\nreaching, check-in to the hotel. Guptkashi is located at a distance of 47 km from the holy shrine,\r\nKedarnath. The town holds immense religious importance as it houses famous ancient temples\r\nlike Shree Kashi Vishwanath Temple and Ardhnareshwar Temple. overnight in the hotel/camp.', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(166, 6, 7, 'Guptkashi/Phata  Kedarnath (approx 27 km DRIVE + 19 km TREK)', 'Highlights - Kedarnath Temple, Adi Shankaracharya Temple\r\n\r\nEarly morning after breakfast drive to the helipad from where, you will start to fly to Kedarnath\r\nby helicopter. Mandakini, one of the main tributaries of the Ganges originates at Kedarnath and\r\nflows through Gaurikund. \"Jai Bholenath\" chants echo in the mountains. The mists envelop the\r\nmountains and slowly lift away. When you can view the picturesque beauty you are left\r\nmesmerized. Overnight stay at Kedarnath.', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(167, 6, 8, 'Kedarnath Guptkashi / Phata (approx 27 km DRIVE + 19 km TREK)', 'Early morning after breakfast you can come back to the helipad to fly to the Sersi / Phata by\r\nhelicopter. The vehicles are waiting for you in the helipad and youï¿½ll drive to the hotel and\r\nOvernight at Guptkashi.', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(168, 6, 9, 'Guptkashi/ Phata  Pandukeshwar / Badrinath (185 kms / 7 hrs )', 'Highlights - Chopta Peak\r\n\r\nAfter having your breakfast in the morning, check out of the hotel and start driving towards your\r\nnext destination, Badrinath via Joshimath. Badrinath is an important pilgrimage site which holds\r\nimmense importance for both Hindus and Buddhists. Badrinath temple is dedicated to Lord\r\nVishnu and is set at a height of 3133 meter. On arrival check into the hotel. After some rest and\r\nrefreshments you are all set to go to Badrinath Temple for darshan in the evening. But first you\r\nhave to go to Tapt Kund (Hot Spring), take a bath and then go to the temple. Dedicated to Lord\r\nVishnu. Later back to hotel. Overnight stay at hotel.', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(169, 6, 10, 'Badrinath  Rudraprayag', 'Highlights - Mana Village - Vasudhara Falls, Satopanth Lake, Bhim Pul, Saraswati Temple,\r\nGanesh Gufa & Vyas Gufa\r\nAlso see Vishnuprayag, Nandprayag, Karnprayag\r\n\r\nThis morning if we had not visited Badrinath Temple, we could visit for Darshan. Later return to\r\nthe hotel for breakfast. After breakfast check out from the hotel and proceed to Mana Village\r\nwhich is known as the last village of India. Places to visit in Mana Village - Bhim Pool, Vyas\r\nGufa and Vasudhara Falls. Later you drive for Rudraprayag. En-route you can see\r\nVIshnuprayag, Nandprayag, Karanprayag. On reaching Rudraprayag, check-in to the hotel. You\r\ncan relax for the rest of the day.stay overnight at the hotel.', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(170, 6, 11, 'Rudraprayag  Rishikesh', 'Highlights - Rudraprayag, Dhari Devi Temple, Dev Prayag, Ram Jhula, Laxman Jhula\r\n\r\nEarly morning, after breakfast, you drive downhill to Rishikesh, a spiritual city and the Yoga\r\ncapital of the world. Enroute you can visit Mata Dhari Devi Temple. On reaching Rishikesh, go\r\nout for sightseeing. Visit Ram Jhula and Laxman Jhula. Evening you can visit Ganga Aarati at\r\nTriveni Ghat. drop to Hotel. overnight stay in hotel', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(171, 6, 12, 'Rishikesh- Delhi', 'After breakfast check out from the hotel and drive to Delhi', NULL, NULL, NULL, 0, '2025-12-31 09:18:56'),
(230, 8, 1, 'Delhi â€“ Haridwar', 'ickup from Delhi Railway Station, Meet & Assist further drive to Haridwar. Check in Hotel. In the evening visit Har-ki-Pauri to view the holy Ganges Aarti. This is the place where the main bathing takes place. The place is called Brahma Kund, the myths says this is the place where the nectar can dissolved in the holy water of river Ganges. If wish, have a dip here later after viewing Aarti visit the market near the place. Later back to your Hotel for night stay.', NULL, NULL, NULL, 0, '2025-12-31 09:24:01'),
(231, 8, 2, 'Haridwar â€“ Rishikesh', 'Morning visit Haridwar Local Sight Seeing i.e Daksh Prajapati Temple, Ananand Mai Ashram, Parad (Mercury) Shivling in Kankhal Region, Mansa Devi and Chandi Devi (both by ropeway), Maya Devi, Pawan Dham, Bhuma Niketan, Parmarth, Bharat Mata Mandir, Shanti Kunj, Saptrishi Ashram and others.\r\n\r\nLater drive to Rishikesh another ancient place which is famous for its Ashrams and for grand viewing of Ganges. Visit Ashrams, some of which are internationally recognized as centre of Philosophical studies, yoga and meditation. Check in Hotel. In the evening visit Triveni Ghat to view the holy Ganges Aarti. Later back to your Hotel for night stay.\r\n\r\nTriveni Ghat: A sacred bathing spot on the bank of the river Ganga where devotees take holy dips and offer prayers. Devotees bathe here with the belief that the water has the power to purify them. Triveni Ghat is also called because it is believed to be the confluence of the Ganga, the Yamuna and the legendary Saraswati river. It is an interesting place to be at dawn when people make offerings of milk to the river and feed the fish. After sunset, as a part of the Aarti ceremony, lamps are floated on the water and provide a spectacular view.', NULL, NULL, NULL, 0, '2025-12-31 09:24:01'),
(232, 8, 3, 'Rishikesh Delhi', 'After Breakfast, Visit Rishikesh Local Sight Seeing. Later drive to Delhi. Drop at Airport for your onward destination.', NULL, NULL, NULL, 0, '2025-12-31 09:24:01'),
(233, 7, 1, 'Arrival in Varanasi', 'Pickup: Arrive at Varanasi Airport and transfer to your hotel.\r\nActivities: In the evening, attend the Ganga Aarti at Dashashwamedh Ghat and enjoy a Ghat\r\nDarshan.\r\nOvernight Stay: Varanasi', NULL, NULL, NULL, 0, '2025-12-31 09:25:26'),
(234, 7, 2, 'Sarnath & Varanasi Temples Tour', 'Morning: Visit Sarnath, where Buddha delivered his first sermon. Explore the Dhamek Stupa,\r\nChaukhandi Stupa, and Sarnath Museum.\r\nAfternoon: Visit prominent Varanasi temples such as Kashi Vishwanath Temple, Annapurna\r\nTemple, and Sankat Mochan Hanuman Temple.\r\nOvernight Stay: Varanasi', NULL, NULL, NULL, 0, '2025-12-31 09:25:26'),
(235, 7, 3, 'Varanasi to Prayagraj (Allahabad)', 'Morning: Check out from your hotel and drive to Prayagraj (approximately 3 hours).\r\nActivities: Visit Triveni Sangam (confluence of Ganga, Yamuna, and Saraswati), Anand\r\nBhavan, and Allahabad Fort.\r\nOvernight Stay: Prayagraj', NULL, NULL, NULL, 0, '2025-12-31 09:25:26'),
(236, 7, 4, 'Prayagraj to Ayodhya', 'Morning: Check out from your hotel and drive to Ayodhya (approximately 4 hours).\r\nActivities: Visit Ram Janam Bhoomi, the birthplace of Lord Rama.\r\nOvernight Stay: Ayodhya', NULL, NULL, NULL, 0, '2025-12-31 09:25:26'),
(237, 7, 5, 'Ayodhya Tour', 'Activities: Explore other significant sites in Ayodhya, such as Hanuman Garhi, Kanak\r\nBhawan, and Sita Ki Rasoi.\r\nOvernight Stay: Ayodhya', NULL, NULL, NULL, 0, '2025-12-31 09:25:26'),
(238, 7, 6, 'Departure from Ayodhya', 'Check Out: Check out from your hotel.\r\nTransfer: Drop off at Ayodhya Railway Station or Airport for your next destination.', NULL, NULL, NULL, 0, '2025-12-31 09:25:26'),
(317, 15, 1, '02:30 AM: - Pickup from Delhi', 'You will be picked up from your hotel in Delhi or any other convenient location to begin your Taj Mahal tour. Drive to Agra (243.4 km) along the Yamuna Expressway.', NULL, NULL, NULL, 0, '2025-12-31 09:31:13'),
(318, 15, 2, '06:00 AM: -Arrival in Agra', 'Reach Agra and then get ready for your visit to the Taj Mahal after a quick pit stop for some tea and refreshments.', NULL, NULL, NULL, 0, '2025-12-31 09:31:13'),
(319, 15, 3, '06:30 AM: - Visit the Taj Mahal', 'This is the highlight of your sunrise Taj Mahal tour, as you enter the historic monument that was built between 1631 and 1648 in Agra by Mughal Emperor Shah Jahan as a tribute to his wife Mumtaz Mahal. The key highlight of your visit is that you can see the UNESCO World Heritage Site at sunrise as the rays fall on the ivory-white marble faï¿½ade and create an unforgettable experience.', NULL, NULL, NULL, 0, '2025-12-31 09:31:13'),
(320, 15, 4, '08:00 AM: - Breakfast Stop', 'After youï¿½re done exploring the Taj Mahal at sunrise, the next pit-stop will be at a local restaurant near the monument for a hearty local breakfast. Savor the rich flavors of Agra as you dig into a hearty meal here.', NULL, NULL, NULL, 0, '2025-12-31 09:31:13'),
(321, 15, 5, '09:00 AM: - Journey to the Agra Fort', 'The next destination on your sunrise Taj Mahal tour from Delhi is the Agra Fort. It was built in 1565 AD by Mughal Emperor Akbar. Explore the sprawling complex which includes the Musamman Burj where Shah Jahan was imprisoned and passed away. This fort was the main residence of the Emperor until the year 1638 when the capital shifted away to Delhi.', NULL, NULL, NULL, 0, '2025-12-31 09:31:13'),
(322, 15, 6, '10:30 AM: - Trip to the Local Bazaars', 'Enjoy a unique experience on your sunrise Taj Mahal tour as you stroll through Agraï¿½s famous local bazaars. Purchase handicrafts and souvenirs along with buying the famous Petha sweets to take back home from your trip. You may choose the Sadar Bazaar near the Agra Cantonment railway station and browse leather items, shoes, souvenirs, and street food here. Another option is the Tajganj Market, which is just near the Taj Mahal and offers souvenirs, handicrafts, marble items, and gifts.', NULL, NULL, NULL, 0, '2025-12-31 09:31:13'),
(323, 15, 7, '12 PM- Return to Delhi', 'Wind up your sunrise Taj Mahal tour and get set for the drive back to Delhi, bringing the curtains down on an awe-inspiring experience.', NULL, NULL, NULL, 0, '2025-12-31 09:31:14'),
(354, 17, 1, 'Arrive at Delhi', 'As per your flight schedule our represntative pickup you from Delhi Airport and transfer you to Delhi hotel. over night rest in Delhi hotel.', NULL, NULL, NULL, 0, '2025-12-31 09:35:36'),
(355, 17, 2, 'Delhi Guiding Tour', 'After Breakfast for full day side sightseeing like the Red Fort, Chandni Chowk Bazaar and Khari Baoli spice market on your way to visit Jama Masjid. One of the largest mosques in the world and the largest in India, it was built by Shah Jahan to dominate the city. Then, make your way to Raj Ghat, a memorial built to commemorate the site of Mahatma Gandhi\'s cremation. Also visit the UNESCO World Heritage-listed Qutub Minar, India\'s tallest minaret, made of red sandstone and marble and inscribed with verses from the Qur\'an.', NULL, NULL, NULL, 0, '2025-12-31 09:35:36'),
(356, 17, 3, 'Delhi - Jaipur. (260 km 6 hrs)', 'After breakfast depart from Delhi to Jaipur around 6 hour drive. evening check in Jaipur hotel.\r\nOver night rest in Jaipur hotel.', NULL, NULL, NULL, 0, '2025-12-31 09:35:36'),
(357, 17, 4, 'Jaipur', 'today proceeds to \'Pink City\' Jaipur. After Breakfast, Visit Amber - the ancient capital of the Rajput Empire reaching the fort on elephant back. It is a deserted palace surrounded by majestic ramparts & the magnificent public & private room\'s evidence the splendor of the rulers of 16th & 17th century Rajasthan. Also visit City Place, Janter Mantar and Hawa Mahal in evening leisure. Overnight at Hotel.', NULL, NULL, NULL, 0, '2025-12-31 09:35:36'),
(358, 17, 5, 'Jaipur:- Agra (200 Kms / 04 hrs)', 'After breakfast drive to Agra en-route visit Fatehpur Sikri. Later continue drive to Agra. Arrive and check in at Hotel. Akbarabad, as Agra was known during the Mughal era, is home to some of the most magnificent Mughal architectures. Situated on the banks of river Yamuna, the monumental beauty of Agra has inspired countless people around the world. This third largest city of the state of Uttar Pradesh is home to three UNESCO world heritage sites. Overnight at Hotel.', NULL, NULL, NULL, 0, '2025-12-31 09:35:36'),
(359, 17, 6, 'Agra - Varanasi', 'On day 06 of Delhi Agra Jaipur Varanasi Tour, Early morning at the time of sun rise visit the Taj mahal (best time to visit the Taj Mahal). after the Taj mahal back to the hotel for breakfast and visit the Agra Fort (world heritage site, baby Taj. Sikandra (tomb of Akbar). late evening catch the night train from Agra to Varanasi.', NULL, NULL, NULL, 0, '2025-12-31 09:35:36'),
(360, 17, 7, 'Varanasi Arrival & City Tour', 'Arrive at Varanasi station. Meet and transfer to hotel for check in. Dating back to more than 3000 years, Varanasi is said to be the oldest city of the world. There are temples at every few steps here Hinduism it is believed that those who breathe their last in this city attain nirvana and get an instant gateway to liberation from the cycle of births and re-births. After Lunch proceed for tour planned for second half of the day We begin the tour of the city with the famous Banaras Hindu University.', NULL, NULL, NULL, 0, '2025-12-31 09:35:36'),
(361, 17, 8, 'Varanasi City Tour', 'Early morning proceed to morning Cruise on Ganges. The \'Ghats of Ganga\' dotted with temples or more than 100 ghats (banks) alongside the Ganges in Varanasi. The best way to cover them all is acruise. A morning cruise on the Ganges presents a very beautiful view of the ghats bathed in crimson light. After Lunch half day excursion to Sarnath. Evening explore the city. A walk through old Varanasi will be memorable experience.', NULL, NULL, NULL, 0, '2025-12-31 09:35:36'),
(362, 17, 9, 'Varanasi Departure', 'Morning catch the train or flight from Varanasi to Delhi. driver pickup you from Delhi Train station/Airport. If you left some sight in Delhi you can visit today. evening driver transfer you Airport to catch your Early morning flight from Delhi. Tour to Varanasi ends.', NULL, NULL, NULL, 0, '2025-12-31 09:35:36'),
(1053, 14, 1, 'Arrival Delhi Airport', 'You will be met at the airport by one of our representatives upon arrival in Delhi, who will pick you up and give you a warm welcome. Check in at the hotel after the transfer. Enjoy a walking tour of Old Delhi local market once you\'ve had a chance to freshen yourself. We will visit Sis Ganj Sikh Temple, Jama Masjid and the spice market.\r\n \r\nOvernight stay in Delhi.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1054, 14, 2, 'Delhi - Agra', 'After breakfast, get driven to Agra. On arrival and check in, visit Agra Fort. Later, enjoy some Mughal cuisine lunch and then visit the lovely Taj Mahal. \r\n \r\nReturn back to the hotel after a long day for overnight stay.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1055, 14, 3, 'Agra -Jaipur', 'oday after breakfast we will drive to the â€˜Pink Cityâ€™- Jaipur. Enroute explore the ghost city of Fatehpur Sikri. On arrival, check into the hotel and relax. Later, head out to witness the majestic Amer Fort with a photo stop at Hawa Mahal and Jal Mahal.\r\n \r\nOvernight stay in Jaipur.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1056, 14, 4, 'aipur - Bikaner', 'oday after breakfast we will have another exciting journey towards Bikaner. After arrival and check in, explore the Junagarh Fort and Karni Mata Temple in Deshnok. \r\n \r\nReturn back to the hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1057, 14, 5, 'Bikaner - Jaisalmer', 'After having breakfast we will head off to the golden sand city of Jaisalmer. Once checked in, visit Bada Bagh at sunset. Rest of the day at leisure.\r\n \r\nOvernight stay in Jaisalmer', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1058, 14, 6, 'Jaisalmer - Khuri', 'Drive to Khuri village and check into the resort after breakfast. Enjoy a desert camel safari in Thar. Dinner served in the evening with a customary traditional dance programme.\r\n \r\nStay for the night in Khuri.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1059, 14, 7, 'Khuri - Jaisalmer', 'Get driven back to Jaisalmer after breakfast. After arrival and check in, visit the grand golden fort and revisit the history.\r\n \r\nAnother overnight stay in Jaisalmer.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1060, 14, 8, 'Jaisalmer - Jodhpur', 'Take a drive to Jodhpur after breakfast. When you get to Jodhpur, check into your hotel. Visit the Spice Market, Jaswant Thada, and Mehrangarh Fort afterwards.\r\n \r\nOvernight stay in Jodhpur.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1061, 14, 9, 'Jodhpur', 'Enjoy a full day tour in Jodhpur after breakfast. Visit Umaid Bhawan Palace and enjoy a jeep safari to Bishnoi village and learn about local culture.\r\n \r\nReturn to the hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1062, 14, 10, 'Jodhpur - Udaipur', 'This morning after breakfast, get driven to â€˜City of Lakesâ€™- Udaipur. After check in, relax and enjoy the rest of the time as you may please.\r\n \r\nOvernight stay in Udaipur.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1063, 14, 11, 'Udaipur', 'Full day is dedicated to sightseeing after breakfast. Visit City Palace, Jagdish temple, Gem Museum, Sahelion ki Baari and enjoy a boat ride in Lake Pichola.\r\n \r\nStay for another night in Udaipur.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1064, 14, 12, 'Udaipur - Mumbai Flight', 'After breakfast, board a flight to Mumbai- the commercial capital of India. On arrival, check in and head out to seek blessings at Siddhi Vinayak temple and spend the rest of the time at Juhu Beach.\r\n \r\nOvernight stay in Mumbai', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1065, 14, 13, 'Mumbai', 'his morning a visit to Elephanta caves is planned. After breakfast, drive to witness the Gateway of India from where we will also embark on a ferry for Elephanta Island. Once you arrive, enjoy the scenic short hike and explore the ancient caves. Return to the mainland after exploration and spend the rest of the time at leisure.\r\n \r\nHotel stay in Mumbai.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1066, 14, 14, 'Bollywood Tours', 'Enjoy breakfast and Visit Bollywood the movie shooting etc \r\n \r\nStay for another night in Mumbai.', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1067, 14, 15, 'Drop Mumbai Airport', 'After breakfast driver drop to Mumbai Airport', NULL, NULL, NULL, 0, '2026-01-06 07:10:56'),
(1102, 10, 1, 'Sight Seeing of Delhi', 'Welcome to the Pink City! Upon arrival, you\'ll be greeted and transferred to your hotel. After check-in, explore local markets or enjoy a short sightseeing tour including Birla Mandir and Nahargarh Fort for a sunset view.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1103, 10, 2, 'Delhi- Mandawa Drive', 'Check in Hotel and get ready for afternoon sightseeing tour in the fort town of Mandawa, famous for its heritage Havelis and fresco art. Thousands of tourists come here to see the Mandawa Castle, which was an important station in the silk route. Now Castle Mandawa has been converted into a beautiful heritage hotel. Night halt at Bikaner', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1104, 10, 3, 'Mandawa - Bikaner Drive', 'Lalgarh-palaceCheck in Hotel & enjoy the afternoon sightseeing tour. A leisurely afternoon visit includes are the major attractions like the Lalgarh Palace, the Junagarh fort, Ganga Golden Jubilee Museum, the Bhandasar Jain Temple, The Gajner Palace, the Shiv Bari Temple including Kalibangan, a famous Harappan civilization site. Night halt at Bikaner', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1105, 10, 4, 'Bikaner - Jaisalmer Drive', 'At Jaisalmer morning sightseeing tour of Jaisalmer, covering beautiful locations like the 12th century Jaisalmer Fort, Gadsisar Lake, Nathmalji-ki-Haveli, Patwon -ki-Haveli, Salim Singh-ki-Haveli and Jain Temple & in the afternoon an exciting trip to Sand dunes and camel safari, night Halt at Jaisalmer.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1106, 10, 5, 'Jaisalmer -Jodhpur Drive', 'Drive to Jodhpur and check-in at a hotel. Jodhpur has several major tourist attractions like Umaid Bhawan Palace, Girdikot and Sardar Market famous for a wide range of handicrafts. Night halt at Jodhpur.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1107, 10, 6, 'Jodhpur Tour', 'Mehrangarh-Fort Sightseeing of Jodhpur including Mehrangarh Fort and Jaswant Thada built in 1899 A.D. in memory of Maharaja Jaswant Singh II. An afternoon sightseeing trip will cover all these destinations. Night halt at Jodhpur.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1108, 10, 7, 'Jodhpur -Udaipur Drive', 'While driving to Udaipur enroute visit Ranakpur Temples, This huge temple complex is located just 90 km from Udaipur city. These are the most extensive of Jain temples in India, covering an area of around 40,000 square feet. Check-in at the hotel for overnight.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1109, 10, 8, 'Udaipur Tour', 'Jag-MahalCity sightseeing tour, Major tourist attractions in Udaipur are Lake Pichola, the largest and the most beautiful of Udaipurâ€™s lakes, City Palace, on the banks of the Lake Pichola, island palaces like Jag Mahal and Jag Niwas, Jagdish Temple, Sahelion Ki Bari, Gulab Bagh (Rose garden) and the 18th century monsoon palace, Sajjangarh. Spend leisure time during afternoon.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1110, 10, 9, 'Udaipur-Pushkar Drive', 'Sightseeing of the holy city of Pushkar, You will get an opportunity to see various religious traditions and rituals practiced in India. Pushkar has several beautiful temples like Brahma Temple, Rangaji Temple, and Savitri Temple, holy ghats and lakes like the famous Pushkar Lake and Night stay in Pushkar.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1111, 10, 10, 'Pushkar-Jaipur Drive', 'Sightseeing tour of Jaipur, visiting sprawling Havelis, serene temples and well laid out gardens of Jaipur, enjoy the architectural excellence of Amber Fort, City Palace, Jantar Mantar, Hawa Mahal and shop for the unique handicrafts of local people. Night halt at Jaipur Drive to Ranthambhore, afternoon jeep safari to view Wildlife. Ranthambore National Park is spread over in an area of 392 sq. kilometrtes.Night stay in Jaipur.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1112, 10, 11, 'Jaipur- Ranthambore Drive', 'After Jaipur sightseen you drive to Ranthambore National Park , check-inn in the hotel and night stay in ranthambore city.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1113, 10, 12, 'Ranthambhore Forest Tour', 'Ranthambore-National-ParkMorning & afternoon jeep safari to view wildlife, Ranthambore National Park is home of variety of animals like Tiger, sambhar, cheetal, wild boar, leopard, sloth bear, and jackal. Night halt at Ranthambhore.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1114, 10, 13, 'Ranthambore-Agra Drive', 'Taj-MahalSightseeing tour of Agra, visiting Taj Mahal, Agra Fort, Jehangir Mahal, Diwan-i-Khas, Diwan-i-Am and Moti Masjid experience the traditional art and craft of Agra like the famous fine marble inlay work and other handicraft products. Night halt at Agra.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1115, 10, 14, 'Agra Delhi Delhi', 'Reaching Delhi after a 204 km long comfortable drive & night stay in Delhi.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1116, 10, 15, 'Delhi Airport transfer', 'Next day after breakfast we will transfer to Airport/Railway station.\r\nPlease note that this is all flexible tour itinerary according to your comfort if you want any change or tailor made itinerary , its will be possible.', NULL, NULL, NULL, 0, '2026-01-06 07:13:30'),
(1141, 11, 1, 'Pickup from airport /train station', 'Pickup from airport /train station and transfer to hotel, Refresh than after start Delhi tour by car and visit sight Old Delhi â€“Red Fort-Jama Masjid-RajGhat-Humayan tomb-India Gate-President House of India-Qutab Miner & night stay in Delhi', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1142, 11, 2, 'Delhi - Agra Drive', 'Pickup from hotel and drive to Agra, check-in in the hotel and refresh after visit Agra fort & Taj Mahal and some local area walking tour â€“Night stay in Agra.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1143, 11, 3, 'Agra-Fathepur Sikri-Jaipur Drive', 'Pick from hotel and drive to Jaipur en-route visit world heritage site fathepur sikri and after continue drive to Jaipur-night stay in Jaipur.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1144, 11, 4, 'Jaipur Tour', 'This morning after breakfast you visit Amber fort-Water palace-city palace-wind palace-monkey temple and some walking in bazaar-night stay in Jaipur.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1145, 11, 5, 'Jaipur - Pushkar Driver', 'This day after breakfast you drive to next holy city Pushkar, arrived in Pushkar and check-in the hotel, in evening you enjoy the Pushkar city and night stay in Pushkar.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1146, 11, 6, 'Pushkar - Udaipur Drive', 'Pickup from hotel and drive to Lake City Udaipur, reach around in evening and some evening tour in the city- night stay in Udaipur.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1147, 11, 7, 'Udaipur - Jodhpur Drive', 'This morning after breakfast check-out and start sight seen and visit fathe Sagar Lake and city palace, Jagdish temple and after lunch drive to next city Jodhpur â€“night stay in jodhpur.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1148, 11, 8, 'Jodhpur - Jaislmer Drive', 'Breakfast and Check-out after visit Jodhpur fort and some more sight seen after lunch drive to Next city Jaislmer-night stay in Jaislmer.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1149, 11, 9, 'Jaislmer - Kuri Tour', 'This morning after breakfast check-out and sight seen in the city, visit most famous attraction after drive to Kuri Desert. Arrive in desert and after start desert tour by camel and night stay in desert camp.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1150, 11, 10, 'Kuri - Bikaner Drive', 'After breakfast you drive to next city Bikaner, check inn in the hotel and after in evening you visit Bikaner fort â€“Night stay in Bikaner.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1151, 11, 11, 'Bikaner - Mandwa Drive', 'Drive to heritage village Mandwa and reach in evening-night stay in Mandwa.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1152, 11, 12, 'Delhi - Mandwa Drive', 'Visit Mandwa walking tour and see the many old Havali, Houses after sight seen- Night stay in Delhi.', NULL, NULL, NULL, 0, '2026-01-06 07:15:41'),
(1153, 12, 1, 'Sight Seeing of Delhi', 'Red-FortThis morning is at leisure. Enjoy a whole daylong extravaganza of visiting New Delhi and Old Delhi. Enjoy the delicious cuisine and visit magnificent monuments like Qutab Miner, Red Fort, India Gate, Jama Masjid, Rajghat Night halt in Delhi.', NULL, NULL, NULL, 0, '2026-01-06 07:16:46'),
(1154, 12, 2, 'Delhi - Agra Drive', 'Pickup from hotel and drive to Agra, check-in in the hotel and refresh after visit Agra fort & Taj Mahal and some local area walking tour â€“Night stay in Agra.', NULL, NULL, NULL, 0, '2026-01-06 07:16:46'),
(1155, 12, 3, 'Agra-Fathepur Sikri-Jaipur Drive:', 'Pick from hotel and drive to Jaipur en-route visit world heritage site fathepur sikri and after continue drive to Jaipur-night stay in Jaipur.', NULL, NULL, NULL, 0, '2026-01-06 07:16:46'),
(1156, 12, 4, 'Jaipur Tour', 'Hawa-Mahalthis morning after breakfast you visit Amber fort-Water palace-city palace-wind palace-monkey temple and some walking in bazaar-night stay in Jaipur.', NULL, NULL, NULL, 0, '2026-01-06 07:16:46'),
(1157, 12, 5, 'Jaipur-Udaipur Drive', 'Pickup from hotel and drive to Lake City Udaipur, reach around in evening and some evening tour in the city- night stay in Udaipur.', NULL, NULL, NULL, 0, '2026-01-06 07:16:46'),
(1158, 12, 6, 'Udaipur - Jodhpur Drive', 'This morning after breakfast check-out and start sight seen and visit fate Sagar Lake and city palace, Jagdish temple and after lunch drive to next city Jodhpur â€“night stay in jodhpur.', NULL, NULL, NULL, 0, '2026-01-06 07:16:46'),
(1159, 12, 7, 'Jodhpur-Jaislmer Drive', 'Breakfast and Check-out after visit Jodhpur fort and some more sight seen after lunch drive to Next city Jaislmer-night stay in Jaislmer.', NULL, NULL, NULL, 0, '2026-01-06 07:16:46'),
(1160, 12, 8, 'Jaislmer-Kuri Tour', 'This morning after breakfast check-out and sight seen in the city ,visit most famous attraction after drive to Kuri Desert. Arrive in desert and after start desert tour by camel and night stay in desert camp.', NULL, NULL, NULL, 0, '2026-01-06 07:16:46'),
(1161, 12, 9, 'Kuri-Jaislmer-Mandwa-Drive', 'Drive to heritage village Mandwa and reach in evening-night stay in Mandwa.', NULL, NULL, NULL, 0, '2026-01-06 07:16:46'),
(1162, 12, 10, 'visit Mandwa', 'Walking tour and see the many old Havali, Houses after sight seen drive to New Delhi and night stay in Delhi.', NULL, NULL, NULL, 0, '2026-01-06 07:16:46'),
(1202, 5, 1, 'Delhi - Manali', 'On arrival at Delhi, our representative meets you and assists to transfer you to Manali 570 km/ 11 hrs. On arrival check in at hotel, freshen up and enjoy rest of the time at leisure. At night enjoy delicious dinner and overnight stay t the hotel in Manali.', NULL, NULL, NULL, 0, '2026-01-06 07:45:17'),
(1203, 5, 2, 'Manali Sightseeing', 'Morning after breakfast get ready for city tour to visit some of the magnificent attractions including Hadimba Devi Temple, Tibetan Monastery, Manu Temple and Vashisht Village. Afternoon enjoy at leisure. Dinner and overnight stay will be at the hotel in Manali.', NULL, NULL, NULL, 0, '2026-01-06 07:45:17'),
(1204, 5, 3, 'Manali Excursion', 'Enjoy the early morning breakfast at the hotel. Later visit to Kothi Gorge, Marhi, Rothang pass and Marhi. Rothang Pass is an important tourist spot with alluring view of the snow capped Himalayas, picturesque lakes and scintillating tranquil surrounding. After visiting to Solang Valley, return back to the hotel on time and enjoy delicious dinner and overnight stay. .( in Winter Car will be going only up to the Snow point).', NULL, NULL, NULL, 0, '2026-01-06 07:45:17'),
(1205, 5, 4, 'Manali - Manikaran via Kullu - Manali', 'Morning after breakfast, check out from the hotel and drive to Manikaran 75 kms /4 hours, enroute visiting Kullu. Manikaran is located in Parvati valley amidst the river Vyaas and Parvati in the Kullu district of Himachal Pradesh. Manikaran is holy centre of both Hindu and Sikh religion. It is believed that Manu created human life again in Manikaran after the devastating flood, making the place centre of pilgrimage. After visit to Manikaran transfer to Kullu valley (45 kms/2 hours) for a half day sightseeing tour and panoramic view of the natural beauty and snow capped himalayas. Return to Manali by evening for dinner and overnight stay at the hotel.', NULL, NULL, NULL, 0, '2026-01-06 07:45:17'),
(1206, 5, 5, 'Manali - Delhi', 'Morning after breakfast, check out from the hotel and transfer to Delhi 520 K M (10 hrs).', NULL, NULL, NULL, 0, '2026-01-06 07:45:17'),
(1225, 67, 1, 'Delhi to Shimla (Approx. 350 km / 7–8 hrs)', 'ick-up from Delhi (home / hotel / airport / railway station) and drive towards Shimla in a comfortable private car. Enjoy scenic mountain views en route. On arrival, check-in at hotel and relax. Evening free for leisure or local walk. Overnight stay in Shimla.', NULL, NULL, NULL, 0, '2026-01-06 09:16:11'),
(1226, 67, 2, 'Shimla & Kufri Sightseeing', 'After breakfast, proceed for local sightseeing of Shimla and Kufri. Visit Kufri Fun World, Jakhoo Temple, Mall Road, The Ridge and Christ Church. Enjoy shopping and local cuisine at Mall Road. Overnight stay in Shimla.', NULL, NULL, NULL, 0, '2026-01-06 09:16:11'),
(1227, 67, 3, 'Shimla to Manali (Approx. 250 km / 7 hrs)', 'Post breakfast, check-out and drive to Manali. En route visit Kullu Valley, Pandoh Dam, Sundernagar Lake and optional river rafting in Kullu. Continue towards Manali. Check-in at hotel and rest. Overnight stay in Manali.', NULL, NULL, NULL, 0, '2026-01-06 09:16:11'),
(1228, 67, 4, 'Manali Local Sightseeing', 'After breakfast, explore local attractions of Manali including Hadimba Devi Temple, Vashisht Hot Springs, Manu Temple, Van Vihar and Mall Road. Evening free for shopping or leisure activities. Overnight stay in Manali.', NULL, NULL, NULL, 0, '2026-01-06 09:16:11'),
(1229, 67, 5, 'Solang Valley / Atal Tunnel Excursion', 'After breakfast, proceed for an excursion to Solang Valley (subject to weather conditions). Enjoy adventure activities like paragliding, skiing, snow scooter and zip-lining (at own cost). Visit Atal Tunnel (if accessible). Return to Manali. Overnight stay in Manali.', NULL, NULL, NULL, 0, '2026-01-06 09:16:11'),
(1230, 67, 6, 'Manali to Delhi (Approx. 540 km / Overnight Drive / 12 hrs)', 'After breakfast, check-out and drive back to Delhi by private car with beautiful memories of the Himalayas. Drop at desired location in Delhi.', NULL, NULL, NULL, 0, '2026-01-06 09:16:11'),
(1339, 56, 1, 'Arrival at Delhi', 'Once you arrive at the Delhi Airport, the tour representative takes charge and helps in transfer to the pre- booked hotel. After checking in you may freshen up and head to the bazaars of Chandni Chowk or any cool lounge restaurant. For a typical punjabi cuisine, you may feel the essence of it at the dhabas of Delhi. Relax at the hotel after a scrumptious meal', NULL, NULL, NULL, 0, '2026-01-06 10:01:38'),
(1340, 56, 2, 'Delhi – Corbett', 'Post breakfast, leave for Corbett National Park by road. It is almost 270 kms from the capital. At the pre booked resort you check in and relax in the room. Post lunch a small orientation is held on Corbett National Park. After this you can enjoy the walk through the jungle and explore its rich wildlife and tiger watching.', NULL, NULL, NULL, 0, '2026-01-06 10:01:38'),
(1341, 56, 3, 'Dhikala', 'Depart to Dhikala by road after breakfast in Corbett. On the way you can see some wildlife activities. At Dhikala, check in at the resort. Later at Dhikala enjoy the game drive. For lunch, get back to the resort and then head on for an adventurous elephant ride. Get your cameras ready as this is home to the most beautiful species of birds and you can watch them closely. The sounds of the birds fill the forest with music. After this amazing experience, go back to the resort and have dinner.', NULL, NULL, NULL, 0, '2026-01-06 10:01:38'),
(1342, 56, 4, 'Corbett National Park', 'Post breakfast, head towards the Ramganga reservoir. Here you get an ariel view of the surroundings from a top Observation Tower. Its an absolute delight for the birdwatchers. Here they can explore and observe birds such as storks, kingfishers, terns, fish eagles and so on', NULL, NULL, NULL, 0, '2026-01-06 10:01:38'),
(1343, 56, 5, 'Corbett – Delhi (Departure', 'At the Corbett National Park make your early morning encounter with the elephants or deer or even a Tiger by taking a game safari. Post safari, enjoy a great breakfast spread at the resort. Depart for Delhi Airport by road post breakfast.', NULL, NULL, NULL, 0, '2026-01-06 10:01:38'),
(1344, 55, 1, 'Delhi Arrival', 'Transfer to hotel by private Car', NULL, NULL, NULL, 0, '2026-01-06 10:02:13'),
(1345, 55, 2, 'Delhi mathura drive', 'Destination and Places to Cover\r\n\r\nMathura : Shri Krishna Janmabhoomi ( Birth Place of Lord Krishna ), Potara Kund, Dwarkadheesh Temple, Vishram Ghat, Birla Temple\r\n\r\nVrindavan : Shri Banke Bihari Temple, Nidhivan, ISKCON, Prem Mandir, Rangnath Temple, Vaishno Devi-night stay mathura', NULL, NULL, NULL, 0, '2026-01-06 10:02:13'),
(1346, 55, 3, 'Mathura Agra Drive', 'Now Take A Short Tea Or Coffee Break To Get You Refreshed! Now Drive Towards Agra.\r\nAfter three And A Half Hours Of Drive, You Will Arrive In The Beautiful City Of Agra. Arrive Agra, Our Executive Will Introduce The Tour Guide-visit tajmahal and Agra fort-night stay Agra', NULL, NULL, NULL, 0, '2026-01-06 10:02:13'),
(1347, 55, 4, 'Agra -Ayodha Drive', 'After agra tour drive to the land of the shree ram , arrive in evening', NULL, NULL, NULL, 0, '2026-01-06 10:02:13'),
(1348, 55, 5, 'Ayodha Sightseen', 'Darshan timing for Ram Mandir in Ayodhya is from 7:00 AM to 11:30 AM in morning while in evening darshan timing is 2:00 PM to 7:00 PM.\r\n\r\nRam Mandir Temple Ayodhya Aarti Timings:\r\n\r\nMorning Aarti - 6:30 AM\r\nAfternoon Aarti - 12:00 PM\r\nEvening Aarti - 7:30 PM\r\n\r\n1) Ram Mandir:- The magnificent Ram Mandir is ready with 1st floor and Vigrah of Shree Ram. Spanning in 54,700 sq ft, the temple area covers nearly 2.7 acres of land. The entire Ram Mandir Complex would be spread over nearly 70 acres and will be equipped to host about a million devotees at any time. The Mandir dimensions are 380 feet length, 161 feet height and 250 feet wide. The temple situated near Saryu River is built in traditional Nagar architectural style. The Temple with 392 pillars will have main Sanctrum, Mandaps. There are four temples on corners dedicated to Sun God, Lord Ganesha, Goddess Bhagwati and Lord Shiva.', NULL, NULL, NULL, 0, '2026-01-06 10:02:13'),
(1349, 55, 6, 'Ayodha Sightseen', 'Hanuman Garhi Temple:- This temple dedicated to Lord Hanuman is one of the most visited temples in Ayodhya and situated on hill top. Devotees and visitors climb a series of stairs to reach the Hanuman Garhi temple complex. The main deity in the temple is Lord Hanuman, and the idol is enshrined in a small cave-like structure.\r\n3) Kanak Bhawan:- Kanak Bhawan is a palace made of gold is said to be gifted by Kaikeyi to Goddess Sita where you will find idols of Lord rama and Sita.\r\n4) Dashrath Mahalaya Palace Museum:- This museum showcases artifacts and exhibits related to the history and culture of Ayodhya. It is located within the complex of the Dashrath Bhavan.\r\n5) Treta Ke Thakur:- An ancient temple that is believed to be the place where Lord Rama performed the Ashwamedha Yagya.\r\n6) Swarg Dwar:- Translated as the \"Gateway to Heaven,\" it is believed to be the spot from where Lord Rama is said to have entered heaven. Devotees believe that passing through this gate ensures a place in heaven after death.\r\n7) Nageshwarnath Temple:- Dedicated to Lord Shiva, this temple is considered one of the oldest in Ayodhya. It is believed to have been established by Lord Rama\'s son, Kush.\r\n8) Kala Ram Temple:- This temple is dedicated to Lord Rama and showcases idols in black stone. It is known for its unique architecture and religious importance.\r\n9) Guptar Ghat:- A serene ghat on the banks of the Sarayu River, associated with the story of Lord Rama and his sons. It is a peaceful spot for reflection and prayer.', NULL, NULL, NULL, 0, '2026-01-06 10:02:13'),
(1350, 55, 7, 'Drop Lucknow-Train or Airport', 'Drop Lucknow-Train or Airport', NULL, NULL, NULL, 0, '2026-01-06 10:02:13'),
(1351, 54, 1, 'Delhi Arrival', 'Meet and assist by our representative upon your arrival at the airport and drive to hotel, Rest after Delhi Private Trip-\r\n\r\nRed Fort-Old Delhi-Rajghat-India Gate-Humyun tomb-lotus temple-Qutab miner', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1352, 54, 2, 'Delhi –Bikaner by Car', 'After breakfast in drive to Bikaner via Mandawa, visit Mandawa and see the local village life-stay in Bikaner', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1353, 54, 3, 'Bikaner Jaislmer-By Car', 'After breakfast drive to Jaislmer city is one of India most beautiful, colorful & fascinating place. Arrive Jaislmer check in at Hotel. Stay Jaislmer', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1354, 54, 4, 'Jaislmer Sightseen', 'After a relaxed breakfast proceed for full day sightseeing tour of The Golden City – Jaislmer. It is in the heart of the Great Indian Desert. Its temple, fort and palaces are all built of yellow stone. The city is a mass of intricately carved buildings, facades and elaborate balconies. visit the Jaislmer fort-oldest living fort , Desert Camel ride etc-Stay Jaislmer .', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1355, 54, 5, 'Jaislmer Jodhpur by Car', 'After breakfast drive to Jodhpur the Gateway to the Thar Desert. Arrive Jodhpur check in at hotel. After visit Jaswant Thada and Meharangarh-Stay Jodhpur', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1356, 54, 6, 'Jodhpur Ranakpur by Car', 'After breakfast drive to Ranakpur visit world famous 500 years old incredible jain temple with 1444 pillar, all pillar are different then each other. After jain temple visit to natural lake with very nice view of sun set-Stay Ranakpur', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1357, 54, 7, 'Ranakpur Udaipur by Car', 'After Ranakpur drive to Udaipur –the city of the lakes , arrive and stay in Udaipur', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1358, 54, 8, 'Udaipur Sightseen', 'This morning after breakfast visit Udaipur and see the nice lakes and life etc-Stay in Udaipur', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1359, 54, 9, 'Udaipur Pushkar by Car', 'After breakfast drive to Pushkar edge of the desert lies the tiny tranquil town of Pushkar along the bank of the picturesque Pushkar Lake. This is an important pilgrimage spot for the Hindus, which has the only temple of Lord Brahma in the country and one of the few in the world. Stay Pushkar', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1360, 54, 10, 'Udaipur Jaipur by Car', 'After breakfast proceed to Jaipur the capital of Rajasthan, arrive Jaipur and check-inn and after the city tour.', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1361, 54, 11, 'Jaipur Sightseen', 'Drive  to the Hawa Mahal, Jantar Mantar, City Palace , wind Palce amber fort  and the in-house Museum. Walk along the bazaars of the “Pink City” and enjoy the colorful life of the city. You will be amazed at the sight of the men and the women folk dressed in the most colorful way, especially ladies adorned with heavy silver jewelry-Stay Jaipur', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1362, 54, 12, 'Jaipur Ranthambore-National Game Park', 'After breakfast drive to Ranthambore national park, arrive afternoon and relex-stay Ranthambore', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1363, 54, 13, 'Ranthambore-National Game Park Safaris', 'This morning visit game park 6:00 am –11:00 am Jeep safari and 2nd safari 14:00 pm to 18:00 Pm –\r\n\r\nHere you have chance to see many animal and Indians tigers-night stay in Ranthambore', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1364, 54, 14, 'Ranthambore-Agra by Car via fatepur sikri', 'After breakfast check out from the hotel and drive to city of marble Agra via fatepursikri-Stay Agra', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1365, 54, 15, 'Tajmahal Visit and drive to Khajuraho', 'Visit Tajmahal morning (sunrise) after breakfast and drive to Kamasutra city Khajuraho-Stay Khajuraho.', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1366, 54, 16, 'Khajuraho Tour', 'After breakfast in hotel proceed to explore beautiful town Khajuraho. Khajuraho known for its temples built from 950 A.D to 1150 AD, by the Candela Dynasty. The group of thirty temples urahois an example of Indian architectural excellence The Western group of temples are best known for their erotic sculptures. Stay Khajuraho', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1367, 54, 17, 'Khajuraho Varanasi Flight', 'Driver drop you Khajuraho airport and flight to Varanasi , pickup Varanasi airport and move to the hotel\r\n\r\n After we take you to banks of the river Ganges where we board a boat to see the morning ablutions of the Hindus from the security of our boat.See the Kashi Vishwanath temple and the Gyanvyapi kund and the mosque attached to it. Also visit the Benares Hindu University the largest residential university in India with more than 3000 residential students', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1368, 54, 18, 'Varanasi Stay', 'Varanasi Sightseeing', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1369, 54, 19, 'Flight back to New Delhi', 'Flight back to New Delhi', NULL, NULL, NULL, 0, '2026-01-06 10:02:45'),
(1370, 53, 1, 'Delhi Arrival', 'Our Company persons meet you in New Delhi airport and transfer to hotel', NULL, NULL, NULL, 0, '2026-01-06 10:06:14'),
(1371, 53, 2, 'Delhi Day Tour', 'This morning after breakfast you start Delhi tour and you visit Red fort, Jama masjid, Rajghat, old Delhi, India gate Huyuman tomb, lotus temple , some temple in the city and you take nice lunch and dinner in the city and night stay in Delh', NULL, NULL, NULL, 0, '2026-01-06 10:06:14'),
(1372, 53, 3, 'Delhi -Agra –Drive', 'This Morning after breakfast you drive to Agra city ( the Taj Mahal) check-in in the hotel and refresh after you start Agra tour and you visit Agra Fort /Baby Taj Mahal and in evening you see the nice sunset from back sight of Taj Mahal and night stay in Agra.', NULL, NULL, NULL, 0, '2026-01-06 10:06:14'),
(1373, 53, 4, 'Agra- Fathepur sikri -Ranthambore Drive', 'This morning pickup from your hotel and transfer to Taj Mahal and you see nice sunrise in the taj Mahal, enjoy the taj and after beck to the hotel and refresh and breakfast after drive to Ranthambore and night stay in Ranthambore', NULL, NULL, NULL, 0, '2026-01-06 10:06:14'),
(1374, 53, 5, 'Ranthambore Jeep Tour (Morning & Afternoon)', 'This morning we provide you jungle tour by jeep, the first tour is 6 am and 2nd tour is 14:00 PM and night stay in hotel.', NULL, NULL, NULL, 0, '2026-01-06 10:06:14'),
(1375, 53, 6, 'Ranthambore- Jaipur Drive', 'Breakfast & Check-out from Ranthambore hotel and drive to pink city Jaipur (the capital of Rajasthan and after continue drive to Jaipur & check-in in the hotel and night stay in Jaipur.', NULL, NULL, NULL, 0, '2026-01-06 10:06:14'),
(1376, 53, 7, 'Jaipur Tour', 'This morning we visit world famous amber fort and there you also enjoy the elephant ride and after we visit water palace, city palace, wind palace and some local area and monkey temples and Night stay in Jaipur.', NULL, NULL, NULL, 0, '2026-01-06 10:06:14'),
(1377, 53, 8, 'Jaipur – Delhi Drive', 'This day you drive back to new Delhi and drop you at airport', NULL, NULL, NULL, 0, '2026-01-06 10:06:14'),
(1383, 50, 1, 'Arrival at Delhi', 'Arrival at the international airport in Delhi late in the night or midnight. Transfer to your hotel.Overnight will be at Delhi', NULL, NULL, NULL, 0, '2026-01-06 10:16:54');
INSERT INTO `package_itinerary` (`id`, `package_id`, `day_number`, `title`, `description`, `meals`, `accommodation`, `activities`, `display_order`, `created_at`) VALUES
(1384, 50, 2, 'Delhi', 'After Breakfast, Start a full-day tour of Old and New Delhi.\r\nOLD DELHI - A sight-seeing tour of Old Delhi would entail visiting the Raj Ghat - the memorial site where Mahatma Gandhi was cremated; Jama Masjid - the largest mosque in India and the Red Fort - once the most opulent fort and palace of the Moghul Empire. Enjoy the cycle rickshaw ride from Jama Masjid to Chandni Chowk.\r\n\r\nNEW DELHI - An extensive sight-seeing tour of New Delhi would include a visit to the Humayun\'s Tomb, the Qutub Minar, a drive along the ceremonial avenue - Rajpath, past the imposing India Gate, Parliament House, the President\'s Residence, Lotus Temple and would end with a drive through the Diplomatic Enclave. Overnight will be at Delhi.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1385, 50, 3, 'Delhi - Agra', 'Start for Agra early in the morning after breakfast. Check in at Agra hotel.\r\nAGRA: Two great Mughal monarchs, Akbar and Shah Jahan, transformed the little village of Agra into a befitting second capital of the Mughal Empire - giving it the name Dar-ul-Khilafat {seat of the Emperor}.\r\n\r\nTAJ MAHAL: Little needs to be said about this architectural wonder which is always the soul raison-de-etre for every tourist\'s visit to Agra. Built by Shah Jahan, the Taj is a white marble memorial to his beautiful wife Mumtaz Mahal. This monument took 22 years to be completed and was designed, and planned by Persian architect Ustad Isa. Proceed for visit to the Taj Mahal, Agra Fort and Itmadullah\'s Tomb (Baby Taj) with English speaking guide. Enjoy battery van ride. Return to hotel and relax in the evening. Overnight will be at Agra.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1386, 50, 4, 'Jaipur', 'Enjoy your breakfast at the hotel. Proceed for a morning excursion to Amber Fort. Elephant ride ascent to the fort', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1387, 50, 5, 'Jaipur - Delhi', 'After breakfast proceed for shopping. Leave for Delhi after lunch. Reach Delhi and you will be transferred to airport for flight with sweet memories of India.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1388, 50, 6, 'Delhi - Chennai', 'Transfer to hotel.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1389, 50, 7, 'Chennai - Trivandrum', 'Transfer to Resort', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1390, 50, 8, 'Ayurvedic Beach Resort', 'Relax and enjoy the facilities at the resort including private beach, yoga, massage, nature walks, classical music and dance programs on open-air stage, visits to local traditional village.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1391, 50, 9, 'Backwaters of Kerala', 'From the resort drive to the pier to board a private rice boat (70 kms/2 hrs drive) and then cruise through the narrow canals and wide lakes enjoying the scenic natural beauty -- coconut trees, rice patties, small villages. Meals and overnight on houseboats.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1392, 50, 10, 'Backwaters - Cochin Morning', 'relax on houseboat, after lunch drive to Cochin 65 Kms/ 1 1/12 hrs.), transfer to hotel. overlooking the harbor, sea facing rooms.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1393, 50, 11, 'Cochin Full day sighseeing', 'palaces, museums. Enjoy a Kathakali dance performance at Cochin Cultural Center, arriving by 5 pm to watch the make-up. Dinner at traditional Kerala restaurant. overnight at hotel.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1394, 50, 12, 'Periyar', 'Periyar Wild life Sanctuary Home to bison, antelopes, sambars, wild boars, monkeys, langurs, a wide variety of birds, and some 750 elephants. Game viewing by private motor-boat in the evening, (the best time to see wild life). overnight at hotel', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1395, 50, 13, 'Periyar - Madurai', 'Relax at Periyar in the morning. In afternoon, drive to Madurai (135 kms./ 4hrs. drive), \"The Temple City of India.\" Evening relaxed overview of the city, independent strolling. Hotel in Madurai, cottages', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1396, 50, 14, 'Madurai', 'Full day sighseeing: Sri Meenakshi Temple, Tirumalai Nayak Palace, Tiruparankundram (rock-cut)Temple, Alagarkoil Temple Evening fly Madurai-Madras dep 19:40 arr 20:30 arr. OR 20:40 dep.-21:30 arr. Hotel', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1397, 50, 15, 'Madras', 'Full day sightseeing of Madras: Kapaleeshwarar Temple, San Thome Cathedral, Sri Parthasarathy Temple, Fort St. George, the Marina. overnight at hotel.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1398, 50, 16, 'Drive to Kanchipuram', 'Visit temples of Kanchipuram enroute to Mahabalipuram. Kailasanatha Temple, Vaikunta Perumal Temple, Sri Ekambaranathar Temple, Kamakshi Amman Temple, Devarajaswami Temple. On arrival in Mahabalipuram transfer to Hotel.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1399, 50, 17, 'Mahabalipuram', 'Morning relax; afternoon sightseeing: Five Rathas, Shore Temple, ArjunaÕs Penance, Mandapams, Krishna Mandapam.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1400, 50, 18, 'Madras', 'Relax in the morning. Late afternoon drive back to Madras (80kms./2hrs. drive). Transfer to international airport for flight home.', NULL, NULL, NULL, 0, '2026-01-06 10:16:54'),
(1401, 49, 1, 'Delhi To Shimla', 'Arrival at Delhi railway station / Airport, our special vehicle pick up you & drive you to Shimla (345 Kms / 9 Hrs). When ever reach at Shimla check into your hotel & get fresh. Evening free for leisure & take your dinner at hotel. Overnight stay at hotel in Shimla.', NULL, NULL, NULL, 0, '2026-01-06 10:18:09'),
(1402, 49, 2, 'Shimla / Kufri Sightseeing', 'After breakfast proceed for wonderful day excursion to Kufri. In Kufri enjoy a walk through thick ceder woods to Mahasu Pick for amazing view of mighty Himalayas. Enjoy Hirse riding at your own cost. You can do wonderful photography also. Evening come back to the Resort & do some shopping at very famous Mall road of Shimla. Enjoy your dinner at Hotel. Overnight stay at hotel in Shimla.', NULL, NULL, NULL, 0, '2026-01-06 10:18:09'),
(1403, 49, 3, 'Shimla To Manali', 'After taking breakfast transfer to Manali (250 Kms/ 8 Hrs). When ever reach at Manali check into your Hotel & get fresh. Take your dinner at Hotel. Overnight stay at hotel in Manali.', NULL, NULL, NULL, 0, '2026-01-06 10:18:09'),
(1404, 49, 4, 'Manali / Rohtang Pass Snow Point Sightseeing', 'After breakfast proceed for full day local sightseeing of Manali like Hadimba Temple, Tibetan Monastery, Lord Buddha and Tankha paintings, Vashistha Temple for \"Hot & Cold water Kund\", Club House. Afternoon excursion to the Rohtang Pass also called Snow Point of Himachal – enjoy the beauty of year round snow caped mountains. Evening free for leisure & enjoy your dinner at Hotel. Overnight stay at hotel in Manali.', NULL, NULL, NULL, 0, '2026-01-06 10:18:09'),
(1405, 49, 5, 'Manali To Delhi', 'After breakfast, checkout from hotel and proceed for Delhi by Road (12hrs.). Reach at Delhi at Night. Overnight at Delhi', NULL, NULL, NULL, 0, '2026-01-06 10:18:09'),
(1406, 49, 6, 'Delhi - Agra - Delhi', 'Today after breakfast we proceed for Agra by Yamuna Express Highway thru this highway we reach agra by 2.30hrs. Today we cover Taj Mahal and Agra Fort.\r\nTAJ MAHAL - Built by Shah Jahan, the Taj is a white marble memorial to his beautiful wife Mumtaz Mahal. This monument took 22 years to be completed and was designed, and planned by Persian architect Ustad Isa.\r\n\r\nAGRA FORT - Fort built in red sandstone with its magnificent palaces, halls of public and private audience and the beautiful gardens. This is where Emperor Shah Jahan was kept under house arrest by his third son Aurangzeb and spent the last year of his life viewing the Taj Mahal from across the river Jamuna. Evening after finish all sight seeing we proceed for Delhi by Road.', NULL, NULL, NULL, 0, '2026-01-06 10:18:09'),
(1407, 49, 7, 'Delhi Sightseeing', 'Today After breakfast we checkout from hotel and proceed for Delhi local Sight seeing as per time permit we proceed for Red Fort / Qutab Minar / India Gate / Parliament House / Akshardham temple / Birla Temple. / Lotus Temple. Drop at Railway Station / Airport.', NULL, NULL, NULL, 0, '2026-01-06 10:18:09'),
(1427, 45, 1, 'Arrive New Delhi Airport', 'On arrival at New Delhi airport and our driver meet you with your name plate and transfer to Hotel and night stay in Delhi.', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1428, 45, 2, 'Delhi City Day Tour', 'This morning after breakfast first you will visit old Delhi. The Raj Ghat, Red fort & Jama Masjid are important places to visit, you may also visit Chandni Chowk, spice market etc. Later on proceed to visit the New Delhi. The Qutab Miner, tallest stone tower in India, imposing India Gate and the Rastrapathi Bhawan, Laxmi Narayan Temple, Lotus Temple and night stay in Delh', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1429, 45, 3, 'Delhi-Agra Drive', 'This morning after breakfast you will drive to love city Agra, check-in in the hotel and refresh and after start Agra tour. You visit Agra fort, Meatab Garden and some local market, Night stay in Agra', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1430, 45, 4, 'Agra – Jaipur Drive', 'This morning after breakfast you will drive to pink city Jaipur ( the capital of Rajasthan) en-route visit Step wall and fathepur sikri and reach in evening in Jaipur and night stay', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1431, 45, 5, 'Jaipur City Day Tour', 'After Breakfast visit amber fort and enjoy the elephant ride and after visit water palace , City Palace , Wind Palace , Monkey Temples and in evening the time for shopping and night stay in Jaipur', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1432, 45, 6, 'Jaipur – Delhi Drive', 'After Breakfast drive back to New Delhi and night stay in Delhi.', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1433, 45, 7, 'Delhi -Cochin by flight', 'Today you will be transferred to airport to take a flight to Cochin. On arrival at Cochin Pickup & Transfer to hotel Rest of the day is at your leisure. Overnight at hotel', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1434, 45, 8, 'Cochin City Tour', 'On arrival at Cochin pick up and transfer to Hotel This evening enjoy Motor Boat Ride at Cochin Harbor and walk around the beach. Overnight at the hotel', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1435, 45, 9, 'Cochin –Munnar Drive', 'After breakfast Cochin sightseeing – Drive to Munnar and night stay in Munner', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1436, 45, 10, 'Munnar City Tour', 'Full day sight-seeing at Munnar – Rajamalai, Mattupetty, Eco point, Devikulam, Tea plantations /overnight at hotel', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1437, 45, 11, 'Munnar- Kumarakom Drive', 'Breakfast at the hotel & later drive to Kumarakom located on the Southern coast of India enjoys a well-balanced tropical climate, upon arrival check-in at Hotel Abad Whispering palms. The village of Kumarakom is a cluster of little islands on the Vembanad Lake sanctuary. Rest of the day is free. Overnight at hotel', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1438, 45, 12, 'Kumarakom City Tour', 'After breakfast at the Hotel visit Kumarakom Bird Sanctuary, the best time for this is between November and March, when a range of migratory birds from Siberia make it their winter home. Some of the species include the Snake bird Little Cormorant, Crow Pleasant, White-branded water Hen and Tree pie. Occasionally you can catch the native kingfishers setting the waters ablaze in a psychedelic flash of colors. The night herons, the Golden-backed woodpeckers are added delights. At the fourteen-acre bird sanctuary one can glimpse many a rare bird – some of which, sadly, may not be around forever. Evening enjoy the sun set cruise thereafter return to hotel for overnight', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1439, 45, 13, 'Kumarakom to Alleppy-Houseboat', 'Today morning after breakfast Proceed to Alleppey, Known as the Venice of the East. On arrival check into a traditional House Boat of Kerala Style. Cruise through the back waters is the fabulous way to explore the fascinating beauty of the backwaters. Stay overnight in the House Boat.', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1440, 45, 14, 'Alleppy –Cochin Drive', 'This morning pick up from the house boat and transfer to Cochin. Rest of the day is free at your leisure. Overnight at hotel .', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1441, 45, 15, 'Transfer to Cochin Airport', 'Today you will be transferred to Cochin airport for your onward journey.', NULL, NULL, NULL, 0, '2026-01-06 10:27:27'),
(1442, 44, 1, 'Arrival in Delhi – Sightseeing', 'Pickup from airport and Transfer to hotel and check-inn in after you start Delhi tour and cover sight Old Delhi –Red Fort-Jama Masjid-RajGhat-Humayan tomb-India Gate-President House of India-Qutab Miner & night stay in Delhi', NULL, NULL, NULL, 0, '2026-01-06 10:30:11'),
(1443, 44, 2, 'Delhi –Jaipur Drive', 'check-out from hotel and drive to pink city Jaipur reach around in afternoon and check-in in the hotel –night stay in Jaipur', NULL, NULL, NULL, 0, '2026-01-06 10:30:11'),
(1444, 44, 3, 'Jaipur Guided Day Tour', 'this morning after breakfast you visit Amber fort-Water palace-city palace-wind palace-monkey temple and some walking in bazaar-night stay in Jaipur', NULL, NULL, NULL, 0, '2026-01-06 10:30:11'),
(1445, 44, 4, 'Jaipur-Step wall-Fathepur sikri –Agra Drive', 'Check-out from hotel and drive to Agra and en-route you can visit world heritage site fathepur sikri and after continue drive to Agra visit Taj Mahal and Agra fort –night stay in Agra', NULL, NULL, NULL, 0, '2026-01-06 10:30:11'),
(1446, 44, 5, 'Agra-Khajuraho Drive', 'This morning after breakfast you drive to Khajuraho (the city of the Kama-sutra temples) arrived in evening –night stay in Khajuraho.', NULL, NULL, NULL, 0, '2026-01-06 10:30:11'),
(1447, 44, 6, 'Khajuraho Day Tour-Evening Flight to New Delhi', 'Pickup from hotel and transfer to Khajuraho Airport and catch flight to New Delhi –Pickup from New Delhi Airport and transfer to hotel or Airport.', NULL, NULL, NULL, 0, '2026-01-06 10:30:11'),
(1448, 43, 1, 'Arrival in the Capital City – Delhi', 'Kick off your journey in vibrant Delhi, where the old meets the new. Upon your arrival at Delhi International Airport, you’ll be greeted by our representative and whisked away to your cozy hotel. Take the evening to unwind or stroll around your neighborhood to soak in the lively atmosphere that surrounds you.', NULL, NULL, NULL, 0, '2026-01-06 10:30:47'),
(1449, 43, 2, 'Delhi – Srinagar (by flight)', 'Post breakfast in the hotel proceed for Delhi Airport to board the flight for Srinagar. Check into a houseboat upon arrival. Shikhara (boat) on Dal Lake, Srinagar, Jammu & Kashmir, IndiaHave lunch in the houseboat and later step out for half-day city tour/sightseeing of Srinagar. Situated in the Kashmir Valley, this beautiful city is known for its gardens, lakes and houseboats (also called shikaras).\r\n\r\nEnjoy the sightseeing and visit Mughal Garden, Nishat Bagh (the Garden of Spring) as well as Shalimar Bagh. Enjoy Shikara ride over Dal Lake in evening.\r\n\r\n Get back to houseboat, have dinner and overnight stay there.', NULL, NULL, NULL, 0, '2026-01-06 10:30:47'),
(1450, 43, 3, 'Srinagar – Gulmarg (55 kms, 2 hrs drive one way)', 'Post breakfast in the houseboat depart for full day excursion of Gulmarg. Gulmarg is the most amazing winter resort in the Gulmarg snow during winter,Srinagar, Jammu & Kashmir, Indiavalley. It is famous for its highest golf course and winter skiing. In afternoon tourists may enjoy skiing at their own expense for which an instructor can be hired to guide them about skiing equipment’s (skies, sticks, gloves and goggles).', NULL, NULL, NULL, 0, '2026-01-06 10:30:47'),
(1451, 43, 4, 'Srinagar – Pahalgam (90 kms, 3.5 hrs one way)', 'Today, set off for Pahalgam, a picturesque town perched on the banks of the Lidder River. The beauty of this peaceful valley will leave you in awe as you meander through lush green meadows and stunning views. After a day immersed in nature, return to your hotel in Srinagar for a cozy overnight stay', NULL, NULL, NULL, 0, '2026-01-06 10:30:47'),
(1452, 43, 5, 'Srinagar – Delhi (by flight) – Drive to Jaipur', 'After breakfast, catch your flight back to Delhi, where a local restaurant will serve you a delicious lunch. Next, journey to the royal city of Jaipur, known for its rich heritage and iconic architecture. Upon arrival, check into your hotel and take the evening to relax, shop, or savor the Rajasthani vibe.', NULL, NULL, NULL, 0, '2026-01-06 10:30:47'),
(1453, 43, 6, 'Jaipur Tour', 'Prepare for a day of exploration! Begin with breakfast before heading to the majestic Amber Fort, where you’ll marvel at the stunning architecture. Capture the perfect photo at Hawa Mahal, then visit the City Palace and Jantar Mantar, a UNESCO World Heritage site. Later, dive into the bustling bazaars of Jaipur, where you can shop for handicrafts, jewelry, and souvenirs before returning to your hotel for a restful night.', NULL, NULL, NULL, 0, '2026-01-06 10:30:47'),
(1454, 43, 7, 'Jaipur – Agra', 'Post-breakfast, embark on your journey to Agra. Stop at Fatehpur Sikri, the exquisite former capital of the Mughal Empire—its architectural wonders offer a glimpse into India’s glorious past. Continue to Agra to visit the magnificent Taj Mahal, where you can marvel at its ivory-white marble beauty. End your day with a visit to Agra Fort before settling in for a relaxing overnight at your hotel', NULL, NULL, NULL, 0, '2026-01-06 10:30:47'),
(1455, 43, 8, 'Agra – Delhi (  Departure )', 'On your final day, after an early breakfast, travel back to Delhi. Once you arrive, enjoy a delicious lunch and immerse yourself in the rich history at landmarks such as India Gate and the Lotus Temple. Please take advantage of the late afternoon to shop for last-minute treasures before we arrange your transfer to Delhi International Airport for your onward journey', NULL, NULL, NULL, 0, '2026-01-06 10:30:47'),
(1465, 41, 1, 'Delhi Arrival', 'Upon arrival at the airport, our representative will greet you and help you with the hotel transfer. The evening is leisure or you can visit Sri Bangla Sahib Gurudwara, one of the famous Sikh Gurudwara. Overnight stay at the hotel in Delhi.', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1466, 41, 2, 'Delhi Sightseeing', 'After breakfast start your Delhi Sightseeing tour visiting  Jama Masjid-the largest mosque in India, built in the 17th century. Next drive past Red Fort and enjoy the Rickshaw Ride to\r\n\r\nChandni Chown. Raj Ghat, India Gate, Rashtrapati Bhawan (Presidential Palace), the Parliament House and other colonial buildings. \r\n\r\nLater, you\'ll drive past the New Delhi area to visit the Qutub Minar, Humayun\'s Tomb and the Lotus Temple. Overnight stay at the hotel in Delhi.', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1467, 41, 3, 'Delhi - Jaipur', 'After breakfast, drive toward Jaipur, Pink City, this drive will take approximately 5 hours. Upon arrival check into the hotel and the rest of the day is leisure. Night stay at the hotel or you can explore the nearby area or local market.', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1468, 41, 4, 'Jaipur Sightseeing', 'After breakfast, visit Hawa Mahal (Palace of Winds) to see its beautiful facade and snap a few photos before continuing to the famous Amber Fort, 7 miles (11 km) outside of Jaipur. You\'ll spend a few hours touring this hilltop fort, then go back to Jaipur stopping at Jal Mahal for some good photos. Next is City Palace, which is a perfect example of blended Rajasthani and Mughal architecture. Next, you\'ll visit nearby Jantar Mantar, also called the Solar Observatory. In the evening visit local markets of Jaipur for some shopping time. Overnight stay at the hotel.', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1469, 41, 5, 'Jaipur - Agra', 'Today post breakfast, check out and drive to Agra, the Taj City.  Enroute visit Fatehpur Sikri-a red sandstone city and Abhaneri Step Wells.  Upon arrival check into the hotel and rest for an hour. Later you\'ll head to Agra Fort also known as Red Fort of Agra, built in the 16th century, Itmad-Ud- Daulah and Mehtab Bagh for a sunset view of the Taj. Overnight stay at the hotel.', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1470, 41, 6, 'Agra - Orchha - Khajuraho', 'Early in the morning, get ready and leave for the famous Taj Mahal. Visit this big white marble mausoleum that was built by Shah Jahan for his beloved wife Mumtaz Mahal. This is one of the most famous monuments in the world.\r\n\r\nThen return to the hotel for breakfast and check out. Drive to Agra Railway Station to take a train to Jhansi, upon arrival our driver will pick you up and drive you to Khajuraho en route to visit Orchha. Here you visit Jahangir Mahal, Raj Mahal and Laxmi Narayan Temple. After that, get back on the road to Khajuraho. Upon arrival check into the hotel and rest. The rest of the day is leisure on your own. Night stay at the hotel in Khajuraho.  \r\n\r\nNote: The Taj Mahal is closed on Friday', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1471, 41, 7, 'Khajuraho Sightseeing', 'Enjoy a morning breakfast at the hotel and leave for the Khajuraho Sightseeing. Visit the Eastern & western groups of temples and erotic sculptures that show a vision of eternal, spiritual and physical love. \r\n\r\nAfter lunch, drive approximately 2 hours to visit the Panna National Park, where you can enjoy a Jeep Safari and experience wildlife (Optional Activity). Overnight stay at the hotel in Khajuraho.', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1472, 41, 8, 'Khajuraho - Varanasi', 'Post breakfast, transfer to the Khajuraho Airport to board a flight for Varanasi. Upon arrival, our representative will welcome you and transfer you to the hotel. Check-in at the hotel and the rest. After lunch, drive to Sarnath, located 10 km northeast of Varanasi. Where you visit the Buddhist temple and the Bodhi Tree. Return to your hotel for a night\'s stay.', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1473, 41, 9, 'Varanasi Sightseeing', 'After breakfast, take a boat ride on the Ganges River and make a ferry pilgrimage from one ghat to another. Manikarnika and Harishchandra are the two cremation ghats, where the funeral pyre burns day and night. Every devout Hindu knows that cremation on the Ganges banks and death in Kashi represents an escape from the cycle of life and death. Spend the night in Varanasi.', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1474, 41, 10, 'Varanasi - Delhi', 'After breakfast check out from the hotel and drive to the Varanasi Airport to take a flight for Delhi. Upon arrival our representative will pick you up and transfer to the hotel. Rest of the day is free for your own activity. Night stay at the hotel.', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1475, 41, 11, 'Departure From Delhi', 'This is the last day of your tour with Elefantastic, after breakfast drive to Delhi Airport to take a flight for your onward journey.', NULL, NULL, NULL, 0, '2026-01-06 10:32:34'),
(1476, 40, 1, 'Arrive in Delhi', 'As per your flight schedule driver pickup you from Airport and transfer you to Delhi hotel. Afternoon visit Red fort, Jama Masjid, Qutab Minar, Lotus Temple, Humayun Tomb. Evening rest in Delhi hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:31:41'),
(1477, 40, 2, 'Arrive in Delhi', 'After breakfast visit India Gate, President hose. and depart from Delhi to Agra. around 3 hrs drive. afternoon check in Agra hotel. evening visit Agra fort, Mehtab bag garden. view the Taj Mahal from Garden. over night rest in Agra hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:31:41'),
(1478, 40, 3, 'Agra - Ranthambore', 'Early morning at the time of sunrise visit Taj Mahal (best time to visit Taj Mahal). Aafter the Taj tour back to the hotel for breakfast and and depart from Agra to Ranthambore Tour. Around 4 hrs drive on the way visit Fatehpur sikri (Capital city of Akbar). Evening check in Ranthambore hotel. over night rest in Hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:31:41'),
(1479, 40, 4, 'Ranthambore', 'Early morning visit the Ranthambore park by Jeep Safari. after noon visit Fort. Eevening visit the Rantambore National park again. and over night rest in hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:31:41'),
(1480, 40, 5, 'Ranthambore - Jaipur', 'After breakfast depart from Ranthambore to Jaipur. around 4 hrs drive. Afternoon check in Jaipur hotel. Evening visit Hawa mahal and Jaipur Bazaar. over night in Jaipur hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:31:41'),
(1481, 40, 6, 'Jaipur', 'After breakfast start your guiding tour of Capital city of Rajasthan (Jaipur). Visit - Amber fort with Elephant ride, City Palace, Jantar Mantar (Astronomical sight). Jal Mahal (water Palace), Monkey Temple. Evening free for shopping or over night rest in Jaipur hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:31:41'),
(1482, 40, 7, 'Jaipur to Delhi', 'After breakfast depart from Jaipur to Delhi around 4 hrs. drive as per your flight schedule driver transfer you to Delhi airport. Golden Triangle Tour With Ranthambore design Delhi Agra Jaipur Ranthambore City by City.', NULL, NULL, NULL, 0, '2026-01-08 05:31:41'),
(1491, 38, 1, 'Arrival in Delhi.', 'As per your flight/train schedule driver pickup you from Airport/train station and transfer you Agra. Evening check in Agra hotel. over night rest in Agra hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:34:32'),
(1492, 38, 2, 'Agra - Jaipur.', 'Early morning at the time of sunrise or after the breakfast visit the Taj Mahl (best time to visit Taj Mahal) and visit Agra fort. Depart from Agra to Jaipur around 4 hours drive. on the way visit Fatehpur Sikri (fort).\r\nAnd evening check in Jaipur Hotel. over night stay in Jaipur Hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:34:32'),
(1493, 38, 3, 'Jaipur - Delhi.', 'After Breakfast Start your guiding tour of Jaipur. Visit - Amber fort, City palace, Hawa Mahal, Jantar Mantar, Jal Mahal. around 3/4 pm depart from Jaipur to Delhi around 5 hrs drive. Late evening check in Delhi hotel. Over night stay in Delhi hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:34:32'),
(1494, 38, 4, 'Delhi- Airport/train station drop.', 'After breakfast start your guiding tour of capital city Jaipur tour. Visit- Red fort, Humayun Tomb, Qutab Minar, India Gate, Lotus Temple, President house as per your flight schedule or train Schedule driver transfer you Delhi Airport/Train station', NULL, NULL, NULL, 0, '2026-01-08 05:34:32'),
(1500, 18, 1, 'Arrive in Delhi', 'check-in at hotel. On your Golden Triangle Tour, Fresh Later look at the visit Red Fort, Chandni Chowk, Jama Masjid, Qutub Minar and Humayun\'s Tomb. Overnight at hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:35:17'),
(1501, 18, 2, 'Agra - Jaipur', 'After refreshing breakfast move for Agra the city of love. Upon arrival, enter into the hotel and relax for few minutes and Then visit the Agra fort made with red sand stone by Akbar. Later visit Taj Mahal built by Shah Jahan for his wife Mumtaz Mahal. The charm of this structure is unparallel. It is said that the death of his lovely wife forced him to make this memorial and used 20,000 men as labored for over 17 years to build this image of white marble and expensive stone. Overnight at hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:35:17'),
(1502, 18, 3, 'Agra – Jaipur via Fatehpur Sikri', 'drive to Jaipur enroute visiting Fatehpur Sikri-a perfectly preserved red sandstone “ghost town” which was the estranged capital of mughal emperor Akbar, built in 1569 and deserted when its water supply failed. Arrive Jaipur & transfer to Hotel of Golden TriangleTours. Overnight in hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:35:17'),
(1503, 18, 4, 'Jaipur – Delhi', 'After breakfast,leave hotel to move towards Jaipur is city has ruled out by various royal Rajputs and there are several spots in Jaipur where you can find their royal residences. visit to enjoy Amber Fort with elephant ride. Later visit Royal Palace museum, Jantar Mantar and Hawa Mahal. Evening is fixed for the white Birla temple. Must visit chowki dhani to enjoy Rajasthani cuisines along with Golden Triangle Tourfolk dances, puppet shows, live music, astrology and others! Enter into the hotel and take a night sleep. Overnight at hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:35:17'),
(1504, 18, 5, 'Jaipur – Delhi', 'After breakfast, drive to Delhi. Arrive Delhi check in at hotel. Overnight at hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:35:17'),
(1505, 4, 1, 'Delhi - Shimla (380 kms)', 'On Arrival in Delhi we will meet you and transfer by to Shimla (343 kms / 8 hrs).Shimla is capital of himachal former capital of Britishers also set amidst, the snow copper, shaivalik,mountains which offer some of the most beautifull view of himalaya Reach there and check in hotel Dinner and overnight at Simla.', NULL, NULL, NULL, 0, '2026-01-08 05:36:26'),
(1506, 4, 2, 'Shimla', 'After breakfast,go out for a sightseeing trip to Kufri(14 kms/1 hour). Afternoon half day city tour visiting Indian Institute Of Advanced Studies, Sankat Mochan Temple and Jakhu Temple, Evening free to stroll in the famous shopping place of Shimla town - The Mall & The Ridge. Dinner and Overnight at hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:36:26'),
(1507, 4, 3, 'Shimla - Kasauli (80 Kms/2 hours)', 'After breakfast,transfer to Kasauli.Kasauli is a small,unspoiled hill station in Solan district of Himachal Pradesh,it is far away from the maddening crowds which you find in other cities and hill stations.Day at leisure and dinner and overnight stay at hotel in Kasauli.', NULL, NULL, NULL, 0, '2026-01-08 05:36:26'),
(1508, 4, 4, 'Kasauli', 'After breakfast,go for local sightseeing in the town and near by areas,evening at leisure,one can spend evening tolling in the mall and shopping.Dinner and overnight stay at hotel in Kasauli.', NULL, NULL, NULL, 0, '2026-01-08 05:36:26'),
(1509, 4, 5, 'Departure(Kasauli-Delhi)', 'After breakfast,depart for Delhi(320 kms/7 hours).Tour Ends.', NULL, NULL, NULL, 0, '2026-01-08 05:36:26'),
(1521, 9, 1, 'Delhi Arrival', 'Arrive at Delhi airport and our representative will welcome you. Transfer to the hotel. After freshen up, enjoy the thrills and chills of the place. Start the sight seen with rickshaw ride at the Old Bazaar. Also enjoy the magnificent sight at Jama Masjid, Red Fort & Humayun Tomb. Also enjoy lovely site seen at President House, Raj Ghat and various other places. Get back in the hotel and stay relaxed with our complementary dinner.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1522, 9, 2, 'Delhi – Agra', 'After early breakfast, proceed towards Agra. On the way, you will enjoy the wonderful scenic at Fatehpur Sikri. This monument will certainly fill your spirit with happiness and joy. After having Lunch, you will also witness the mesmerizing site scene at The Taj Mahal – One of the Seven Wonders of the World. Check in at the hotel and overnight stay with our complementary dinner.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1523, 9, 3, 'Agra – Sankasya – Lucknow', 'After early breakfast, move for Lucknow with packed Lunch. En route you will visit famous Buddha Stupa at Sankasya. Enjoy the holy site. Arrive in Lucknow and check in at the hotel with complementary Dinner.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1524, 9, 4, 'Lucknow – Sravasti', 'After breakfast, enjoy the royalty of the City of Nawabs. Get the glance at Chota Imambara, Dilkusha Kothi and various other places on the way to Sravasti. On the way, have Lunch while enjoying the site seen. Arrival at Sravasti and check in at the hotel with our complementary Dinner.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1525, 9, 5, 'Sravasti – Kapilvastu – Lumbini (Nepal)', 'After breakfast, proceed towards Lumbini. On the way, get the glimpse of holistic site at Sravasti where Lord Buddha did miracle to impress the non-believers. En route have Lunch along with the site seeing. Check in at the hotel at Lumbini, overnight stay with complementary Dinner.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1526, 9, 6, 'Lumbini – Kushinagar', 'After breakfast, enjoy the spirituality of Mayadevi Temple which is a UNESCO World Heritage Site and birth place of Buddha. En route have Lunch. Check in at the hotel at Kushinagar and have complementary Dinner at hotel.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1527, 9, 7, 'Kushinagar – Vaishali – Patna', 'After the breakfast, visit Nirvana Chaitya where Buddha achieved the divine knowledge. On the way, you will visit Vaishali. Also enjoy Lunch en route. Arrival in Patna and check in at the hotel with our complementary Dinner.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1528, 9, 8, 'Patna – Rajgir – Nalanada – Bodhgaya', 'After breakfast, visit various sites at Patna. Get the glimpse of the ancient civilization at Rajgir which harbors famous place Makhdum Kund. En route Lunch at the Hotel. Arrival in Bodhgaya and check in at the hotel with complementary Dinner.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1529, 9, 9, 'Bodhgaya', 'After breakfast, start your tour in the spiritual city of Bodhgaya. The city is well known for its architectural monuments in the form of the magnificent temples. Visit the most popular Mahabodhi Temple. Here, Buddha spent years in the search of knowledge. You will get the glimpse of the life of Buddha through museum, house and sculptures. You will get comprehensive knowledge about the life of Buddha while visiting Dungeshwari Cave temples. Here, he spent various phases of life while reaching towards enlightenment. Lunch at the Hotel. After performing religious activities get back in hotel and have overnight stay with complementary Dinner.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1530, 9, 10, 'Bodhgaya – Varanasi', 'After breakfast, proceed towards Varanasi. Check in, Lunch at the hotel. After rest enjoy the mesmerizing site seen. This is another spiritual place for the Buddhists. Get the glimpse at the Sarnath Temple. This is a sacred place where Buddha delivered his first sermon. You mind and soul will certainly get fill with the spirituality of this place. Overnight stay at the hotel with complementary Dinner.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1531, 9, 11, 'Varanasi – Delhi', 'After breakfast, transfer to Delhi.', NULL, NULL, NULL, 0, '2026-01-08 05:46:37'),
(1533, 68, 1, 'Rickshaw Tour of Old Delhi', 'During your rickshaw ride you will get to ride around:\r\n\r\nCHANDNI CHOWK:\r\nChandni Chowk or \"Silver Square\" is the most famous and historic street of Delhi, built around 300 years ago when the walled city of Shahjahanabad was established in the 17th century. Don\'t let the word \"old\" mislead you. The energy of vibrant streets of Chandni Chowk is simply irresistible. This part of Delhi includes street food, vibrant bazaars where you can shop for some ancient artifacts and jewellery.\r\n\r\nJAMA MASJID:\r\nJama Masjid is the last work of Emperor Shah Jahan. Its construction began in 1650 and was completed within six years. You can relive the Mughal or Mogul history of Delhi passing through the splendid corridors of this ancient mosque. The Jama Masjid stands across the road in front of the Red Fort.\r\n\r\nRED FORT:\r\nRed fort or Lal Qila is the most magnificent ancient building of Delhi which was built by the Mughal Emperor Shah Jahan in 1638. Designed by the Mughal architects Ustad Hamid and Ahmad, Red Fort is an important symbolic monument in India even today. Some of the captivating building it encloses are Diwani-am, Diwani-Khas, Rang Mahal, The Pearl Mosque etc.', NULL, NULL, NULL, 0, '2026-01-24 06:39:20'),
(1536, 69, 1, 'OLD DELHI BICYCLE TOUR ( 6:00 Am to 10:00  Am )', 'Explore Old Delhi, once the home of Mughals and now the heart of India, in all its glory on a bicycle tour curated by Delhi veterans. From the bike saddle we will observe the capital city waking up to its chaos and tripping you into its transcendental history. All delivered in an amusing storified format that will leave you awe stuck sometimes and in laughter at times! We will cycle through the narrow lanes of Old Delhi & see more than on foot discovering unimaginably narrow streets, hidden corners and historic monuments (Lal Quila, Chandni Chowk, Jama Masjid, fatehpuri masjid and many more). The experience will culminate over a nice breakfast, new friendships and stories to take home.\r\n\r\nStops Along The Route-\r\nCity wall | Jama Masjid | Local Bread Bakery | Sikh Temple | Spice Market | Ancient Havelis | Breakfast', NULL, NULL, NULL, 0, '2026-01-24 06:48:51'),
(1540, 70, 1, 'Slum Tours Delhi (  3 hours )', 'Sanjay Colony is a small slum built on 25 acres of land located in the south of Delhi near the Bahai Lotus Temple and Iskcon temple. Spend 2 hours walking around and visiting small scale businesses, a small temple, a mosque and residential areas. Learn about working and residential life and witness how despite the challenging living conditions it remains an area charged with positive energy and strong community.\r\n\r\nFamily Lunch: Towards the end of the tour, we will walk to a nearby family home for a vegetarian meal. Not only will you get additional insight into Sanjay Colony, but you’ll provide a local family with some extra income. Get comfortable to feast the local way, sitting on the floor and eating with your hands.\r\n\r\nClothes Recycling & Manufacturing\r\nMany Sanjay Colony families work in the clothing industry. See how materials are painstakingly separated to be recycled and then observe the many factories making the finished items.\r\n\r\nHindu Temple\r\nVisit a small Hindu temple where you will learn about the importance of religion in the residents’ lives.\r\n\r\nResidential Life\r\nUncover the realities of residential life as you wander the narrow lanes with your guide.\r\n\r\nRooftop Visit\r\nIn addition to getting an overview of the maze-like tour route, you will get a stunning view of Sanjay Colony!\r\n\r\nFamily Lunch\r\nAfter the tour, enjoy a vegetarian lunch in a local family’s home.', NULL, NULL, NULL, 0, '2026-01-24 06:54:07'),
(1541, 71, 1, 'ARRIVE COCHIN', 'The ultimate tour begins with India Trip Planners team members who will be overwhelmed in receiving you at Cochin airport and you will be transferred to hotel for your check in. Relax for a while as and when you reach to your hotel. Cochin sightseeing will enrich you with the remarkable history; fascinate you with its amendable culture. So, quickly take a sunset cruise ride along the backwaters of Cochin for experiencing the illuminated views of the Marine Drive and its sides. Stay overnight in the hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:05:09'),
(1542, 71, 2, 'COCHIN', 'Today, you will visit the main tourist attractions of Cochin such as Dutch Palace, Jewish Synagogue, Spice Market, Hill Palace, St.Francis Church, Santa Cruz Basilica and Puthuvype Beach. To spend some romantic time with your partner you can go to Fort Kochi Beach. Later on, watch an amazing Kathakali performance which in known to be famous from its ancient times in Kerala. Return to your hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:05:09'),
(1543, 71, 3, 'COCHIN – PERIYAR', 'After your delightful breakfast, drive to Periyar which is also called as Thekkady on the 3rd day of your trip. It is one of the most popular wildlife sanctuaries in South India. Periyar is an area of serene lakes, dense woods, craggy hills and spice gardens. Check into the hotel as per your arrival. Relax for some time and then in the afternoon, go for sightseeing of this magical place of South India. Later, return to the hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:05:09'),
(1544, 71, 4, 'PERIYAR', 'The day is dedicated for Periyar; so after breakfast start your sightseeing with Periyar Wildlife Sanctuary. Here to get a view of large variety of wildlife species like Wild Elephants, Sambar Deer, Nilgiri Langur, Wild Bison, Wild Boar and also some unique birds; then take a Wildlife cruise. After finishing up with the wildlife sanctuary, explore the Hill Station and Spice Plantation where you can do certain activities like Bamboo Rafting, Trekking and Elephant ride. Later, get back to the hotel for a comfortable night stay.', NULL, NULL, NULL, 0, '2026-01-24 07:05:09'),
(1545, 71, 5, 'PERIYAR – ALLEPPEY', 'This is going to be the ultimate day when you will leave for Alleppey to board onto the Houseboat. Earlier, Houseboats were known as Kettuvallams or Rice Boats which were used as ferries to carry rice, now it has come out in the modern form. You will take your lunch on the houseboat and after that, you will be taken on a cruise through the narrow canals of the Vembanad Lake. The floating markets in canoes and exotic landscapes of rolling paddy fields around all add an ethnic touch to the cruise. The stay is on houseboat itself. So, enjoy the sunset and later do peacefully the gazing of stars which can be rarely done when in crowded cities. Also, enjoy your dinner with the sounds of water gushing through and fro over the moors.', NULL, NULL, NULL, 0, '2026-01-24 07:05:09'),
(1546, 71, 6, 'ALLEPPEY - KUMARAKOM', 'Move to the next destination after breakfast that is Kumarakom. As per your arrival, you will check into the hotel which is already reserved for you. Get the fantastic Ayurvedic treatments of massage and spa which is being offered by the resorts and get relaxed right in the lap of nature. Enjoy the views of greenery and the fascinating beauty of the place in the evening. Overnight stay is at the hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:05:09'),
(1547, 71, 7, 'KUMARAKOM - MARARIKULAM', 'Check out from Kumarakom and then drive to Mararikulam which is a quaint little fishing village and is also known for its ayurvedic therapies. Check into the resort as per your arrival. Later, do the sightseeing of the place and get involved with the locals of Mararikulam. Visit Velorvattom Mahadeva Temple in the evening and then return to the resort for a peaceful night stay.', NULL, NULL, NULL, 0, '2026-01-24 07:05:09'),
(1548, 71, 8, 'MARARIKULAM', 'The full day is going to be at this amazing place where you will relax at the beaches and do fun-filled activities too. So after your breakfast, you will explore Mararikulam Shiva Temple which has idols of Lord Shiva and Parvati Goddess. Next, you will go to The St. Andrews Church which is also known as the St. Sebastian\'s Church in Cherthala which is few km away from Mararikulam. Return and relax at the famous Alappuzha Beach. Overnight stay is at the resort.', NULL, NULL, NULL, 0, '2026-01-24 07:05:09'),
(1549, 71, 9, 'MARARIKULAM – COCHIN DEPARTURE', 'It is the goodbye moment from this tour. India Trip Planners representative will guide you to the Cochin airport to catch the return flight for your onward destination. We serve the best and maintain our values with the best in all amenities. Thank you for giving us a chance to serve you.', NULL, NULL, NULL, 0, '2026-01-24 07:05:09'),
(1551, 72, 1, 'ARRIVE CHENNAI', 'On your arrival at Chennai airport, we will be pleased in receiving you and from there you will be transferred to hotel for your check in. Relax for a while as and when you reach to your hotel. Now, you will begin with your Chennai sightseeing. It is one of the oldest cities which are well known in India. The Dravidian traditions are very well in-sighted at Chennai and also keeping the Indian culture and tradition preserved intact till date. The main tourist attractions in Chennai are St Mary\'s Church, the Fort Museum, Kapaleeshwar Temple and lastly to the Marina Beach for fantastic views of Chennai nature beauty during sunset. Stay overnight in the hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:14:24'),
(1552, 72, 2, 'CHENNAI TO MAHABALIPURAM', 'Check out from Chennai after your breakfast and move towards Mahabalipuram which is approximately 1 hour in distance. As and when your reach, check into the hotel and rest for a while. Later, begin with your sightseeing of this beautiful place. Your start will be by the world heritage site known famously as the Shore Temple which depicts a relic of Pallava art. After that visit, the \"Five Rathas\" which is described as a group of monolithic monuments and animal figures carved out of solid rock. Some more exciting sites in the vicinity of the town are Arjuna\'s Penance, Varaha Mandapam, Krishna Mandapam, and Mahishasurmardhini Caves. Return to your hotel after this fruitful day and relax for the night.', NULL, NULL, NULL, 0, '2026-01-24 07:14:24'),
(1553, 72, 3, 'MAHABALIPURAM TO PONDICHERRY', 'After this super amazing destination Mahabalipuram, next we will do the exploration of another exciting place Pondicherry. So, leave for it in the morning after your delightful breakfast. Check into the hotel after your arrival and relax for some time. In the afternoon, do the excursion of the magical place Pondicherry. The visit starts with Sri Aurobindo Ashram which is one of the most affluent and the spiritualism was performed validating on modern scientific facts and Yoga. Next, from there we will move to next spot Auroville was so developed to help people of different nationalities, creeds and cultures to get together in peace and harmony and find their true self. Enjoy there and then move to Arikamedu, French War Memorial and at the end spend some time at Pondicherry Beach. Return to the hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:14:24'),
(1554, 72, 4, 'PONDICHERRY TO THANJAVUR', 'Today, we are going to explore Thanjavur (Tanjore), so quickly leave from Pondicherry after munching your breakfast. Reach there and get to the pre-booked hotel. After that, begin with your sightseeing of Tanjore. You will visit the Shri Brihadishwara Temple which is the crowning glory of Chola style of temple architecture. This temple consists of big and magnificent halls and shrines. Next, visit the Tanjore Palace & Museum where you will get to see lot of art and architectural statues mostly made up with bronze. Tanjore is also famous for its paintings which are unique and famously known to be as “Thanjavur Paintings”. After the beautiful exploration, return to the hotel and stay for the night.', NULL, NULL, NULL, 0, '2026-01-24 07:14:24'),
(1555, 72, 5, 'THANJAVUR – CHETTINAD – MADURAI', 'Today, you will be transferred to the next destination Madurai and on your way you will halt at Chettinad for its exploration. The architecture of the temples is fantastic. After that, continue your journey towards Madurai. As per your schedule upon arrival, check into the hotel and relax for a while. Henceforth, begin with the exploration of Madurai Meenakshi Temple which based on the consort of Lord Shiva. It attracts the tourists from all over the world. Next visit Thirumalai Nayaka Palace which is very grand and beautifully structured. Return to the hotel for dinner and comfortable night stay.', NULL, NULL, NULL, 0, '2026-01-24 07:14:24'),
(1556, 72, 6, 'MADURAI TO PERIYAR (THEKKADY)', 'Drive to Periyar which is also called as Thekkady on the 4th day of your trip. It is one of the most popular wildlife sanctuaries in South India. Check into the hotel as per your arrival. Relax for some time and then in the afternoon, go for sightseeing of this magical place of South India. Start your sightseeing with Periyar Wildlife Sanctuary. Here to get a view of large variety of wildlife species like Wild Elephants, Sambar Deer, Nilgiri Langur, Wild Bison, Wild Boar and also some unique birds; then take a Wildlife cruise. After finishing up with the wildlife sanctuary, explore the Hill Station and Spice Plantation where you can do certain activities like Bamboo Rafting, Trekking and Elephant ride. Later, get back to the hotel for a comfortable night stay.', NULL, NULL, NULL, 0, '2026-01-24 07:14:24'),
(1557, 72, 7, 'PERIYAR – KUMARAKOM', 'Move to the next destination after breakfast that is Kumarakom. It is situated on the shores of the tranquil Vembanad Lake which is around 14 km from Kottayam. It is the best place in whole Kerala for clicking pictures of the scenic beauty. It caters many small clusters of islands which makes it more beautiful. Kumarakom has become very famous now and it attracts many tourists from all over the world; also it has grown up as a bird sanctuary. It is the best place to be laze upon over holidays, offering beautiful surroundings. There are many things to do additionally such as boating and fishing. After this fun-filled day, you will return to your hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:14:24'),
(1558, 72, 8, 'KUMARAKOM – ALLEPPEY (RICE BOAT)', 'Leave for Alleppey to board onto the Riceboat, the most wanted time to be on the boat. Earlier, Houseboats were known as Kettuvallams or Rice Boats which were used as ferries to carry rice, now it has come out in the modern form. You will take your lunch on the houseboat and after that; you will be taken on a cruise through the narrow canals of the Vembanad Lake. The stay is on houseboat itself. So, enjoy the sunset and later do peacefully the gazing of stars which can be rarely done when in crowded cities. Also, enjoy your dinner with the sounds of water gushing through and fro over the moors.', NULL, NULL, NULL, 0, '2026-01-24 07:14:24');
INSERT INTO `package_itinerary` (`id`, `package_id`, `day_number`, `title`, `description`, `meals`, `accommodation`, `activities`, `display_order`, `created_at`) VALUES
(1559, 72, 9, 'HOUSEBOAT TO COCHIN', 'The last destination to visit is Cochin, so quickly after your delightful breakfast, check out from Houseboat. In the afternoon, India Trip Planners team members will begin with your Cochin sightseeing with the main tourist attractions such as Dutch Palace, Jewish Synagogue, Hill Palace, St.Francis Church and Puthuvype Beach. To spend some romantic time with your partner you can go to Fort Kochi Beach. Later on, visit Marine Drive for taking a glimpse of the sunset. After that, according to your departure schedules, leave for your final destination from there', NULL, NULL, NULL, 0, '2026-01-24 07:14:24'),
(1561, 73, 1, 'ARRIVE COCHIN', 'Taj Mahal Day Tour - OTI team members will be overwhelmed in receiving you at Cochin airport and you will be transferred to hotel for your check in. Relax for a while as and when you reach to your hotel. Now, you will begin with your Cochin sightseeing with the main tourist attractions such as Dutch Palace, Jewish Synagogue, Hill Palace, St.Francis Church and Puthuvype Beach. To spend some romantic time with your partner you can go to Fort Kochi Beach. Later on, visit Marine Drive for taking a glimpse of the sunset. Stay overnight in the hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1562, 73, 2, 'COCHIN – MUNNAR', 'Proceed to your next destination which is Munnar after a delightful breakfast at the hotel. Upon arrival, get to check into the hotel. Begin the sightseeing of Munnar and in evening you can walk through the Munnar Tea Museum and also visit the Cardamom Curing Centre. Spend your night in hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1563, 73, 3, 'MUNNAR', 'Today after your breakfast, you are going to spend a full day sightseeing of this extraordinary place, Munnar. Start quickly without wasting time by exploring Eravikulam National Park which is approximately 30 minutes away from Munnar and Nilgiri Thaars is the main attraction of this park being protected at its best. Return and explore Attukal Waterfalls, Mattupetty Dam, Echo Point, Kundala Lake and Mount Carmel. After that, have your dinner at the hotel and stay for overnight.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1564, 73, 4, 'MUNNAR TO PERIYAR', 'Drive to Periyar which is also called as Thekkady on the 4th day of your trip. It is one of the most popular wildlife sanctuaries in South India. Check into the hotel as per your arrival. Relax for some time and then in the afternoon, go for sightseeing of this magical place of South India. Later, return to the hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1565, 73, 5, 'PERIYAR', 'The day is dedicated for Periyar; so after breakfast start your sightseeing with Periyar Wildlife Sanctuary. Here to get a view of large variety of wildlife species like Wild Elephants, Sambar Deer, Nilgiri Langur, Wild Bison, Wild Boar and also some unique birds; then take a Wildlife cruise. After finishing up with the wildlife sanctuary, explore the Hill Station and Spice Plantation where you can do certain activities like Bamboo Rafting, Trekking and Elephant ride. Later, get back to the hotel for a comfortable night stay.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1566, 73, 6, 'PERIYAR – KUMARAKOM', 'Move to the next destination after breakfast that is Kumarakom. It is situated on the shores of the tranquil Vembanad Lake which is around 14 km from Kottayam. It is the best place in whole Kerala for clicking pictures of the scenic beauty. It caters many small clusters of islands which makes it more beautiful. Kumarakom has become very famous now and it attracts many tourists from all over the world; also it has grown up as a bird sanctuary. It is the best place to be laze upon over holidays, offering beautiful surroundings. There are many things to do additionally such as boating and fishing. After this fun-filled day, you will return to your hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1567, 73, 7, 'KUMARAKOM – ALLEPPEY', 'The most waited day of this trip when you will leave for Alleppey to board onto the Houseboat. Earlier, Houseboats were known as kettuvallams or rice boats which were used as ferries to carry rice, now it has come out in the modern form. You will take your lunch on the houseboat and after that you will be taken on a cruise through the narrow canals of the Vembanad Lake. The stay is on houseboat itself. So, enjoy the sunset and later do peacefully the gazing of stars which can be rarely done when in crowded cities. Also, enjoy your dinner with the sounds of water gushing through and fro over the moors.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1568, 73, 8, 'ALLEPPEY – KOVALAM', 'On 8th day, you will check out from your houseboat after breakfast and proceed to Kovalam. Kovalam beach is a dreamland and famously known as the “Paradise of the South”. It is a destination full of greenery, serenity, and pleasant climate. Reach at the destination and check into the hotel. Rest for some time and then proceed for sightseeing. It is the place where one would be able to see the golden sand at the day time and silver sand in the night time; it is so phenomenal. This beach paradise with high rock promontory and a calm bay of blue waters in total creates a unique aquarelle on moonlight nights. Return to the hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1569, 73, 9, 'KOVALAM – TRIVANDRUM – POOVAR – KOVALAM', 'Proceed for the sightseeing of Trivandrum, after your delightful breakfast. We will begin with the Sri Padmanabhaswamy temple which is the most religious temple of the city. Then we will explore some other places like Kuthiramalika Palace Museum and then followed with Veli Tourist Village which has an excellent waterfront park with an entire range of aqua entertainment facilities like wading pools, fishponds and landscaped garden. Later in the afternoon, head towards Poovar Beach and indulge in the endless beauty of the beach. Later, return to Kovalam and spend a comfortable night.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1570, 73, 10, 'KOVALAM – KANYAKUMARI – KOVALAM', 'Your next destination of this tour plan is Kanyakumari. So, leave for it early in the morning and then after exploration return back to Kovalam for your stay. Kanyakumari was famous as Cape Comorin earlier and is located at the southernmost point of India. It attracts a lot of tourists because it is the geographical end of the mainland. Nagercoil and Thiruvananthapuram are the closest major cities. Kanyakumari is formed on the name of the Hindu Goddess Kanyakumari which is situated at the confluence of the three beautiful water-bodies stated as the Arabian Sea, the Bay of Bengal and the Indian Ocean. After exploring Kanyakumari and watching the mind-blowing sunset, return back to Kovalam and stay for the night.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1571, 73, 11, 'KOVALAM – TRIVANDRUM DROP', 'This is going to be the end of the Kerala exploration. After your breakfast, you will proceed to Trivandrum airport/railway station to connect your flight/train to the onward destination. Thank you for giving us a chance to serve you with this. Return home with sweet memories of your wonderful trip with your loved ones.', NULL, NULL, NULL, 0, '2026-01-24 07:22:22'),
(1572, 74, 1, 'ARRIVE COCHIN - ATHIRAPALLY', 'You will be met on arrival at Cochin International Airport and then get transferred to Athirapally. Athirapally which is positioned at the opening point of the Sholayar forest range, get on the ride to see its unparallel beauty which defies even words. We will start with its mighty waterfalls which is of over 80 ft that cascade down the rocks with a furious roar as it sprinkles you, is the best sight to behold on this Kerala trip. Then from there, we will move to explore Kauthuka Park followed by Charpa Waterfalls for an ultimate bird watching near to it. Later, return to your hotel for a comfortable stay.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1573, 74, 2, 'ATHIRAPALLY - VALPARAI', 'Move to the next super amazing destination famous as Valparai for which you will drive through the reserve forests of Sholayar. It consists of elephants, wild boar, leopards and indigenous Nilgiri Thar and species of wild goat too. After the wonderful journey, you will arrive at Valparai which has many tea and coffee estates, so upon your arrival check in at a tea plantation bungalow on a working tea estate. We have chosen this type of stay so that you can explore all what can be possible. Overnight stay is at the plantation bungalow.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1574, 74, 3, 'VALPARAI', 'After your breakfast with delicious tea, you will explore the country side of Valparai. You will be taken for a walk through the tea estate where you will see and get the complete idea of the plantation workers tending and picking the tea. You will also come across the extraordinary waterfalls in this area and some great attractive reservoirs as well such as Sholayar Dam which is a magnet for birdlife such as Great Indian Hornbill. Later, return to the bungalow and relax for overnight.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1575, 74, 4, 'VALPARAI - MADURAI', 'After Valparai, take a road trip towards Madurai. As per your schedule upon arrival, check into the hotel and relax for a while. Henceforth, begin with the exploration of Madurai Meenakshi Temple which based on the consort of Lord Shiva. It attracts the tourists from all over the world. Next visit Thirumalai Nayaka Palace which is very grand and beautifully structured. Return to the hotel for dinner and comfortable night stay.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1576, 74, 5, 'MADURAI – MUNNAR', 'Proceed to your next destination which is Munnar after a delightful breakfast at the hotel. Upon arrival, get to check into the hotel. Begin the sightseeing of Munnar and in evening you can walk through the Munnar Tea Museum and also visit the Cardamom Curing Centre. Spend your night in hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1577, 74, 6, 'MUNNAR', 'Today after your breakfast, you are going to take a walk in the Tea plantation spots. Later without wasting time, you will be exploring Eravikulam National Park which is approximately 30 minutes away from Munnar and Nilgiri Thaars is the main attraction of this park being protected at its best. Return and explore Attukal Waterfalls, Mattupetty Dam, Echo Point, Kundala Lake and Mount Carmel. After that, have your dinner at the hotel and stay for overnight.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1578, 74, 7, 'MUNNAR - PERIYAR', 'Drive to Periyar which is also called as Thekkady on the 7th day of your trip. It consists of one of the most popular Nature Reserve, Wildlife Sanctuary in the Cardamom Hills of South India. Check into the private bungalow as per your arrival. Relax for some time at the isolated Plantation Bungalow and then in the afternoon avoid more touristy areas, visit the cardamom plantations for which you have chosen this tour. Later, return to the hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1579, 74, 8, 'PERIYAR', 'Today, you will dedicate your day for long rafting cum trekking program through the richest forest tracks of Periyar Tiger Reserve. It will offer you a memorable experience in navigation across the famous Periyar Lake. Apart from only the rafting experience, you will also travel through a mosaic of pristine habitats which is worldly famous. Overnight stay is at the plantation bungalow itself.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1580, 74, 9, 'PERIYAR - ALLEPPEY', 'This is going to be the ultimate day when you will leave for Alleppey to board onto the Houseboat. Earlier, Houseboats were known as Kettuvallams or Rice Boats which were used as ferries to carry rice, now it has come out in the modern form. You will take your lunch on the houseboat and after that explore the beauty by doing the sightseeing of the exotic landscapes. Enjoy your stay and relax at houseboat.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1581, 74, 10, 'ALLEPPEY', 'After your breakfast at the houseboat, you will be taken on a cruise through the narrow canals of the Vembanad Lake. The floating markets in canoes and exotic landscapes of rolling paddy fields around all add an ethnic touch to the cruise. The stay is on houseboat itself. So, enjoy the sunset and later do peacefully the gazing of stars which can be rarely done when in crowded cities. Also, enjoy your dinner with the sounds of water gushing through and fro over the moors.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1582, 74, 11, 'ALLEPPEY - COCHIN', 'You will be transferred to Cochin from Alleppey. Check into the hotel as per your arrival and relax for a while at the hotel. Cochin sightseeing will enrich you with the remarkable history; fascinate you with its amendable culture. So, quickly take a sunset cruise ride along the backwaters of Cochin for experiencing the illuminated views of the Marine Drive and its sides. Stay overnight in the hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1583, 74, 12, 'COCHIN', 'In Cochin, you will begin with your Cochin sightseeing with the main tourist attractions such as Dutch Palace, Jewish Synagogue, Hill Palace, St.Francis Church and Puthuvype Beach. To spend some romantic time with your partner you can go to Fort Kochi Beach. Later on, visit Marine Drive for taking a glimpse of the sunset. Stay overnight in the hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1584, 74, 13, 'DEPARTURE', 'This is the end of your Tea & Wildlife trails package. We will guide you to the Cochin airport to catch the return flight for your onward destination. We serve the best and maintain our values with the best in all amenities. Thank you for giving us a chance to serve you.', NULL, NULL, NULL, 0, '2026-01-24 07:28:41'),
(1585, 75, 1, 'ARRIVE BANGALORE', 'For a fantastic tour, India Trip Planners will meet you at Bangalore International Airport and transfer to your hotel as per your bookings. Get freshen up and then in the afternoon enjoy an orientation tour of Bangalore. Bangalore is the tech-city which consists of many companies and with it; it is a great source of entertainment too for tourists from all over the world. You will enjoy the sightseeing and later get back to the hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1586, 75, 2, 'BANGALORE', 'Exploration of the Bangalore city begins after your delightful breakfast. The weather condition is almost always pleasant here that is why it attracts tourist from all over the world. You will visit Bannerghatta National Park, Ulsoor (Boating), Wonder-la which is a fun-filled place with so many activities, Tipu Sultan’s Summer Palace which is grand, Bangalore Palace is simply outrageous and lastly at the Venkatappa Art Gallery. In the late evening, dedicate your time for attending the grand Aarti in Iskcon Temple which will make you feel peace and glorious. Return back to hotel and night stay is in hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1587, 75, 3, 'BANGALORE – HASSAN', 'Next, you will be checking out from Bangalore and will be moving towards Hassan. Hassan is well-known for its temples and architecture. As per your arrival, you will be transferred to your pre-booked hotel. After getting refreshed from your travel hangover, we will continue our tour with sightseeing of Hassan. Enjoy at Yogakshema Ayurveda Centre and get relaxed. Return and stay comfortably at your hotel in Hassan.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1588, 75, 4, 'HASSAN', 'We will be exploring Hassan today after your breakfast. Today explore the intricately carved Temples such as Kedareswara Temple, Lakshmi Narasimha Temple, Hasanamba Temple and Koravangala Temple. After this sacred visit, you will be taken to Chandragiri Hills which is the soothing location. Then, visit Bhagwan Bahubali Statue, Shettihalli Church, Bisile Ghat and in the end visit Gorur Dam. After this glorious day, you will return to the hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1589, 75, 5, 'HASSAN – MYSORE', 'Today early morning we have to leave for another beautiful destination that is Mysore. As per your arrival, get check-in to hotel. Relax for a while and then start your sightseeing of Mysore. In evening you will visit the very popular Mysore Palace which is also famous by the name Amba Vilas. The lighting on it is spectacularly awesome and worth a visit. Overnight stay is at the hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1590, 75, 6, 'MYSORE', 'The day is dedicated completely to Mysore. You will start exploring the very famous and grand Chamundeshwari Temple, followed by St. Philomena’s Cathedral, Jaganmohan Palace, Melody World Wax Museum, and in the end the Mysore Zoo. Later, you will drive to Sri Rangapattanam to see the Tippu’s Summer Palace which is grand and the ruins of the Tippu’s Fort too. In the evening, you will take a stroll through the colorful fruit and vegetable market at Devaraja Market. Later, get back to the hotel for a comfortable night stay.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1591, 75, 7, 'MYSORE – KABINI', 'Next, we will be moving towards Kabini which is famous for its Jungle Safari. So, leave from Mysore and after arrival at Kabini, get checked into the pre-booked hotel. Get relaxed and then begin with sightseeing of Kabini. You will drive to Nagarhole National Park which is one of the finest Wildlife Parks in South India. Do the safari of one part of this park today and then in the evening time, spend time on the banks of the Kabini River. Overnight stay is at the hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1592, 75, 8, 'KABINI', 'The complete day is for jungle activities at Nagarhole National Park with a guide, in search of the elephant, tiger, sambar, mongoose, spotted deer, peacock and jungle fowl too. Also, visit Kabini Dam and then get into the activity of boating in the evening. The city shopping is also interesting, so spend some time there and then return to your hotel for dinner and overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1593, 75, 9, 'KABINI - COORG', 'In the morning after breakfast, proceed to the hill station of Coorg. In between, you will halt at the Tibetan settlement and Golden Temple at Bylakuppe. Later, continue your journey towards Coorg and on arrival check into your resort. In the evening, visit the famous Namdroling Monastery and then Abbey falls which is named after a British officer’s wife and is best viewed in monsoon season. After this wonderful day, stay at the hotel and enjoy the fantastic views of this pleasant destination Coorg.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1594, 75, 10, 'COORG', 'After your breakfast, you will enjoy a visit to the Dubare Elephant Camp. After that, pay a visit to Omkareshwara Temple which is going to fill you with peace and harmony. Then, head towards Burude Falls where you will get the fantastic views and you will be trekking to reach this amazing falls. Next, you will be visiting Madikeri fort which is very massive and from there to the Gaddige Raja’s Tomb. After that, get involved in the activities such as trekking, river rafting at Barapole River. In the evening, take the tour of Coffee plantation and return to your hotel for night stay.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1595, 75, 11, 'COORG – NILESHWAR', 'A visit to this destination is going to be a lifetime memorable site of this complete Kerala trip. Reach Nileshwar and check into the already reserved hotel room for you. Relax for some time and then do the excursion of this extraordinary place of South India. This is the best place to relax with an Ayurveda massage at a resort. In the evening, you will pay a visit to the renowned Hindustan Kalari Sangam, which is one of the oldest in the world and gives world class training in ‘Kalaripayattu’ that is the Kerala martial arts. Return to the hotel for night stay.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1596, 75, 12, 'NILESHWAR', 'After your delicious breakfast, we will be taking you to the massive Neeleswaram Palace. The architecture style of this palace is remarkable. After that, we will be exploring Shree Muthappan Temple which consists of beautiful hall and shrines. In the end, you will relax at the Azhithala Beach which is the prime and beautiful spot of Nileshwar. Return back to the hotel and stay for overnight.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1597, 75, 13, 'NILESHWAR – COCHIN', 'From Nileshwar, you will be transferred to hotel for your check in at Cochin. Relax for a while as and when you reach to your hotel. Cochin sightseeing will enrich you with the remarkable history; fascinate you with its amendable culture. So, quickly take a sunset cruise ride along the backwaters of Cochin for experiencing the illuminated views of the Marine Drive and its sides. Stay overnight in the hotel.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1598, 75, 14, 'COCHIN', 'Today, you will visit the main tourist attractions of Cochin such as Dutch Palace, Jewish Synagogue, Spice Market, Hill Palace, St.Francis Church, Santa Cruz Basilica and Puthuvype Beach. To spend some romantic time with your partner you can go to Fort Kochi Beach. Later on, watch an amazing Kathakali performance which in known to be famous from its ancient times in Kerala. Return to your hotel for overnight stay.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
(1599, 75, 15, 'COCHIN DEPARTURE', 'Our representatives will assist you to the Cochin airport to catch the return flight for your onward destination. We serve the best and maintain our values with the best in all amenities. Thank you for giving us a chance to serve you.', NULL, NULL, NULL, 0, '2026-01-24 07:37:10'),
