INSERT INTO `tour_packages` (`id`, `category_id`, `title`, `slug`, `short_description`, `description`, `duration_days`, `duration_nights`, `base_price`, `discounted_price`, `price_type`, `featured_image`, `gallery_images`, `video_url`, `max_group_size`, `min_age`, `difficulty_level`, `inclusions`, `exclusions`, `meta_title`, `meta_description`, `meta_keywords`, `is_active`, `is_featured`, `is_bestseller`, `display_order`, `views`, `created_at`, `updated_at`) VALUES
(2, 2, 'Delhi Shimla Manali Delhi Tour Package 6 Days', 'delhi-shimla-manali-delhi-tour-package-6-days', '', 'Experience the beauty of Himachal Pradesh with our Manali Shimla Tour. Explore the snow-capped mountains, lush valleys, and charming colonial architecture. Begin your journey in Shimla, known for its scenic Mall Road, Jakhoo Temple, and historic landmarks. Continue to Manali, where you can visit Solang Valley, Rohtang Pass, and Hadimba Temple, and enjoy thrilling adventures like paragliding and river rafting. Perfect for couples, families, and nature lovers, this tour offers a perfect blend of relaxation and excitement amidst the serene Himalayan landscapes. Book now for an unforgettable mountain getaway.', 5, 6, '0.00', NULL, 'per_person', '6954e8e097266_1767172320.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Delhi Shimla Manali Delhi Tour Package 6 Days', '', '', 1, 1, 0, 0, 73, '2025-12-31 08:52:23', '2026-01-28 17:43:31'),
(4, 2, 'Shimla kasauli tour package', 'shimla-kasauli-tour-package', 'A scenic Himachal tour combining the charming hill stations of Shimla and Kasauli.', 'Experience the beauty of the Himalayas with our 5-day Shimla Tour. Begin your journey from Delhi and enjoy a scenic drive to Shimla, the Queen of Hills. Explore popular attractions like The Ridge, Mall Road, Jakhoo Temple, Kufri, and Chail. Breathe in the fresh mountain air, take in stunning views of snow-capped peaks, and relax in peaceful surroundings. Perfect for families, couples, and nature lovers, this tour offers a blend of sightseeing, leisure, and adventure. Create unforgettable memories with this charming escape to Shimlaï¿½s serene landscapes.', 5, 4, '0.00', NULL, 'per_person', '695f425a6a2fd_1767850586.png', NULL, NULL, 20, 0, 'easy', '', '', 'Shimla Kasauli Tour Package | Himachal Hill Station Holiday', 'Enjoy a refreshing hill station getaway with the Shimla Kasauli Tour Package. Explore the scenic beauty, cool mountain climate, colonial charm and peaceful landscapes of Himachal’s most popular destinations with comfortable travel arrangements and guided sightseeing.', 'Shimla Kasauli tour, Himachal hill station tour, Shimla Kasauli package, hill station holiday, India mountain tour', 1, 0, 0, 0, 61, '2025-12-31 08:53:49', '2026-01-28 17:43:33'),
(5, 2, 'Delhi Manali Delhi Tour Package 5 Days', 'delhi-manali-delhi-tour-package-5-days', '', 'Embark on a mesmerizing 5-day Manali tour and experience the breathtaking beauty of Himachal Pradesh. Begin your journey from Delhi to Manali, driving through scenic valleys and mountains. Enjoy local sightseeing at Hadimba Devi Temple, Vashisht Kund, and Manu Temple. Experience the thrill of adventure at Solang Valley with activities like paragliding and skiing. Explore the enchanting Rohtang Pass (subject to availability) and capture the snow-covered charm. Indulge in shopping at the vibrant Mall Road and enjoy cozy evenings in the hills. A perfect getaway for nature lovers and thrill-seekers.', 5, 4, '0.00', NULL, 'per_person', '6954eacd5c217_1767172813.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Delhi Manali Delhi Tour Package 5 Days  | Shimla Manali Road Trip | Delhi Manali tour package,', '', 'Delhi Manali tour package, Manali tour from Delhi, Himachal road trip, Shimla Manali package, 5 days Himachal tour', 1, 0, 0, 0, 43, '2025-12-31 08:53:50', '2026-01-28 17:43:31'),
(6, 5, 'Chardham Yatra Package from Delhi', 'chardham-yatra-package-from-delhi', '', 'Chardham Yatra Tours is a sacred pilgrimage journey covering the four holy shrines of Yamunotri, Gangotri, Kedarnath, and Badrinath nestled in the majestic Himalayas. This spiritually enriching tour offers a perfect blend of devotion, adventure, and natural beauty. Pilgrims embark on a divine path through serene rivers, ancient temples, and breathtaking landscapes. From the holy Ganga Aarti in Haridwar to the tranquil vibes of Badrinath and Kedarnath, every step of this journey brings peace to the soul. Chardham Yatra is not just a tripï¿½it\'s a transformative experience that renews your spirit and deepens your connection with the divine.', 12, 11, '0.00', NULL, 'per_person', '6954ea754355e_1767172725.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Chardham Yatra Package from Delhi', '', '', 1, 0, 0, 0, 37, '2025-12-31 08:53:50', '2026-01-28 17:43:34'),
(7, 5, 'Varanasi Prayagraj Ayodhya Package', 'varanasi-prayagraj-ayodhya-package', '', 'Explore the spiritual heart of India with our Varanasi, Prayagraj, and Ayodhya tour package. Begin your journey in Varanasi, the city of temples and ghats, where you can witness the mesmerizing Ganga Aarti. Next, visit Prayagraj, known for the sacred Triveni Sangam, where the Ganga, Yamuna, and Saraswati rivers meet. Conclude your pilgrimage in Ayodhya, the birthplace of Lord Rama, and visit the grand Ram Janmabhoomi temple. This thoughtfully curated package offers comfortable travel, guided tours, and spiritual experiences that connect you to Indiaï¿½s divine heritage. Book now for a soulful journey through these sacred cities.', 6, 5, '0.00', NULL, 'per_person', '6954ec05dedb5_1767173125.webp', NULL, NULL, 20, 0, 'easy', '', '', 'Varanasi Prayagraj Ayodhya Package', '', '', 1, 0, 0, 0, 39, '2025-12-31 08:53:51', '2026-01-28 17:43:32'),
(8, 5, 'Delhi Haridwer Rishikesh Delhi 5 Days Package', 'delhi-haridwer-rishikesh-delhi-5-days-package', '', 'According to astrologers, the â€˜Kumbh Fairâ€™ takes place when the planet Jupiter enters Aquarius and the Sun enters Aries. According to mythology, â€˜Devasâ€™ (Gods) and â€˜Asurasâ€™ (Demons) churned the ocean to obtain Nectar and when the coveted â€˜Kumbhaâ€™ (pitcher) of Nectar (Amrita) which gave immortality was obtained from the depths of ocean, one of the â€˜Devasâ€™ whisked away the â€˜Kumbhaâ€™ from the â€˜Asurasâ€™ and evading from the â€˜Asurasâ€™, stopped at four places viz. Haridwar, Allahabad (Prayag), Nasik and Ujjain before he finally arrived into the safety of heaven. A few drops of Nectar are supposed to have spilled over on the water at these four places and sages, saints and pilgrims started periodically to flock to each of these â€˜Tirthasâ€™ to celebrate the divine event. In fact , it is a unique event that blends religious and social features alike', 5, 4, '0.00', NULL, 'per_person', '6954ebb0f3692_1767173040.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Delhi Haridwer Rishikesh Delhi 5 Days Package', '', '', 1, 0, 0, 0, 40, '2025-12-31 08:53:51', '2026-01-29 05:47:49'),
(9, 5, 'Buddha Tours Package India', 'buddha-tours-package-india', 'A spiritual 11-day Buddhist circuit tour covering India’s key pilgrimage destinations.', 'Buddhism is based on the wisdom of Siddhartha Gautam borne like a prince of kapilavastu situated in Lumbini, Nepal. Gautam Buddha attained illumination sitting under the tree of Pipal.\r\n\r\nThis Buddhist tour will get you to the lots of significant Buddhist sites of India and we submit this tour the same as footsteps of Buddha. The major sites to be visiting through this tour are Bodhgaya, Patna, Kushinagar, Balrampur and Lumbini', 11, 10, '0.00', NULL, 'per_person', '6954eb6a807c4_1767172970.webp', NULL, NULL, 20, 0, 'easy', '', '', 'Buddha Tours Package India | Buddhist Trails 10 Nights 11 Days Tour | Buddhist Circuit India', 'Explore India’s sacred Buddhist Trails on this 10 Nights 11 Days tour covering major sites like Bodh Gaya, Sarnath, Kushinagar, Rajgir, Nalanda and Varanasi with cultural experiences, spiritual visits and comfortable travel.', 'Buddhist Trails tour, Buddhist circuit India, Bodh Gaya Sarnath Kushinagar, Buddhist pilgrimage tour, India spiritual tour', 1, 0, 0, 0, 43, '2025-12-31 08:53:51', '2026-01-28 17:43:34'),
(10, 3, '15 Days Rajasthan Tour Package', '15-days-rajasthan-tour-package', '', 'Embark on an unforgettable journey through the majestic land of Rajasthan with our 15 Days Rajasthan Tour Package. Explore the vibrant culture, royal palaces, historic forts, desert landscapes, and colorful markets across the state. This tour is a perfect blend of heritage, adventure, and relaxation, covering iconic cities such as Jaipur, Udaipur, Jodhpur, Jaisalmer, Bikaner, and more. Whether you\'re a history enthusiast, culture lover, or photography buff, this package offers the best of Rajasthan in two weeks.', 15, 14, '0.00', NULL, 'per_person', '6954eb293bb5f_1767172905.jpg', NULL, NULL, 20, 0, 'easy', '', '', '15 Days Rajasthan Tour Package', '', '', 1, 0, 0, 0, 61, '2025-12-31 08:53:51', '2026-01-29 22:53:18'),
(11, 3, '12 Days Rajasthan  Private Tours', '12-days-rajasthan-private-tours', '', 'Uncover the royal legacy of Rajasthan in 12 unforgettable days filled with historic forts, royal palaces, desert adventures, and spiritual journeys. This thoughtfully curated tour offers the perfect blend of cultural richness, scenic beauty, and local experiences across iconic destinations like Jaipur, Udaipur, Jodhpur, Jaisalmer, and more. Ideal for families, couples, and culture lovers, this journey captures the true spirit of Rajasthan in less than two weeks.', 12, 11, '0.00', NULL, 'per_person', '6954ec44292b1_1767173188.jpg', NULL, NULL, 20, 0, 'easy', '', '', '12 Days Rajasthan  Private Tours', '', '', 1, 0, 0, 0, 47, '2025-12-31 08:53:52', '2026-01-29 06:55:25'),
(12, 3, '10 Days Rajasthan Private Tours', '10-days-rajasthan-private-tours', 'Experience the majestic charm of Rajasthan in just 10 days with this carefully crafted tour that takes you through the land of kings, forts, and desert wonders.', 'Experience the majestic charm of Rajasthan in just 10 days with this carefully crafted tour that takes you through the land of kings, forts, and desert wonders. From the royal palaces of Jaipur to the golden sands of Jaisalmer, the blue houses of Jodhpur, and the serene lakes of Udaipur. every city tells a tale of its glorious past and vibrant culture. Ideal for those looking to explore the highlights of Rajasthan within a limited time, this tour offers history, heritage, adventure, and unforgettable local experiences.', 10, 9, '0.00', NULL, 'per_person', '6954ecbeb420a_1767173310.jpg', NULL, NULL, 20, 0, 'easy', '', '', '10 Days Rajasthan Private Tours', '', '', 1, 1, 0, 0, 52, '2025-12-31 08:53:53', '2026-01-29 23:21:45'),
(13, 3, '15 to 18 Days Rajasthan Varanasi Tajmahal Tour Package', '15-to-18-days-rajasthan-varanasi-tajmahal-tour-package', 'A rich cultural tour combining Rajasthan’s royal cities and Varanasi’s spiritual experiences.', 'Experience the royal heritage of Rajasthan and the spiritual charm of Varanasi with this inclusive tour. Explore iconic destinations like Delhi, Agra, Jaipur, Udaipur, Jodhpur and witness the sacred Ganga Aarti in Varanasi. Comfortable travel with cultural sightseeing and memorable experiences.', 18, 0, '0.00', NULL, 'per_person', '6954ec7c55eda_1767173244.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Rajasthan with Varanasi Tour | Delhi Agra Jaipur Udaipur Varanasi Package', '', 'Rajasthan tour, Varanasi tour package, Delhi Agra Jaipur Udaipur Jodhpur Varanasi, Rajasthan Varanasi holiday, India heritage tour', 1, 1, 0, 0, 71, '2025-12-31 08:53:53', '2026-01-30 04:25:16'),
(14, 3, 'Delhi Agra Rajasthan & Mumbai Tours', 'delhi-agra-rajasthan-mumbai-tours', '', 'A tour combining Delhi, Agra, Rajasthan (Jaipur, Jaisalmer, Udaipur), and Mumbai offers a diverse experience of India\'s history, culture, and modernity. You can explore historical sites like the Taj Mahal and Red Fort, enjoy vibrant bazaars and palaces, and experience the energy of Mumbai\'s urban landscape', 20, 0, '0.00', NULL, 'per_person', '6954ee259746a_1767173669.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Delhi Agra Rajasthan & Mumbai Tours', '', '', 1, 0, 0, 0, 55, '2025-12-31 08:53:54', '2026-01-29 19:42:58'),
(15, 4, 'Tajmahal Sunrise Tours', 'tajmahal-sunrise-tours', '', 'The Taj Mahal Sunrise Tour is a magical journey that lets you witness the iconic monument in the soft glow of early morning light. As the sun rises, the white marble of the Taj Mahal shimmers with golden hues, offering a serene and unforgettable view. This early visit allows you to avoid large crowds and enjoy the peaceful ambiance of one of the world\'s most beautiful architectural wonders.', 1, 0, '0.00', NULL, 'per_person', '6954ed614402f_1767173473.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Tajmahal Sunrise Tours', '', '', 1, 0, 0, 0, 66, '2025-12-31 08:53:54', '2026-01-29 23:58:11'),
(16, 4, 'Tajamhal Tour by Train', 'tajamhal-tour-by-train', 'Tajmahal tour by train from Delhi - Tajmahal Tour Train Tickets', 'The Taj Mahal Tour by Train via Gatimaan Express offers a fast, comfortable, and convenient way to explore the beauty of Agra in a single day. Departing from Delhi, the Gatimaan Express is India\'s fastest train, reaching Agra in just 100 minutes. Upon arrival, you\'ll be taken to the majestic Taj Mahal to witness its stunning architecture and learn about its rich history. The tour often includes visits to other iconic sites such as Agra Fort and Mehtab Bagh. With guided support, smooth transfers, and same-day return, this tour is perfect for travelers seeking a hassle-free and memorable experience.', 1, 0, '8500.00', NULL, 'per_person', '6954eeb473975_1767173812.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Taj Mahal Tour by Train, One Day Taj Mahal Tour by Train, Same Day Taj Mahal Tour', 'Enjoy a same day Taj Mahal tour by train from Delhi to Agra. Travel by Gatimaan Express and explore the Taj Mahal, Agra Fort, and local highlights with comfort and speed.', 'Taj Mahal day tour by train, Gatimaan Express Taj Mahal tour, Delhi to Agra train tour, same day Taj Mahal tour by train, Agra day trip by train', 1, 1, 0, 0, 76, '2025-12-31 08:53:55', '2026-01-30 02:53:29'),
(17, 4, 'Tajmahal Tour with Varanasi', 'tajmahal-tour-with-varanasi', '', 'The Taj Mahal Tour with Varanasi combines the grandeur of Mughal architecture with the spiritual essence of India. Begin your journey in Agra with a visit to the iconic Taj Mahal, a timeless symbol of love and architectural brilliance. Then travel to Varanasi, one of the world\'s oldest living cities, to experience the sacred Ganga Aarti, explore ancient temples, and take a serene boat ride on the Ganges. This tour offers a perfect blend of history, culture, and spirituality, giving you an unforgettable glimpse into India\'s rich and diverse heritage.', 9, 8, '0.00', NULL, 'per_person', '6954ee676fcb8_1767173735.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Tajmahal Tour with Varanasi', '', '', 1, 0, 0, 0, 57, '2025-12-31 08:53:55', '2026-01-29 16:26:07'),
(18, 1, 'Golden Triangle with Jaipur  Tour', 'golden-triangle-with-jaipur-tour', 'A classic Golden Triangle tour covering Delhi, Agra and Jaipur’s top heritage attractions.', 'Experience India’s iconic Golden Triangle with the Delhi Agra Jaipur Tour. Visit the majestic Taj Mahal, Agra Fort, Amber Fort, and City Palace while enjoying a culturally rich journey with comfortable transfers and professional service.', 5, 4, '0.00', NULL, 'per_person', '695f4215f012a_1767850517.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Golden Triangle with Jaipur  Tour |  Delhi Agra Jaipur Tour | 4 Nights/ 5 Days  Golden Triangle Tour', 'Experience India’s iconic Golden Triangle with the Delhi Agra Jaipur Tour. Visit the majestic Taj Mahal, Agra Fort, Amber Fort, and City Palace while enjoying a culturally rich journey with comfortable transfers and professional service.', 'Delhi Agra Jaipur tour, Golden Triangle package, Taj Mahal tour, Agra Jaipur Delhi sightseeing, India heritage tour', 1, 0, 0, 0, 125, '2025-12-31 08:53:56', '2026-01-29 07:11:47'),
(38, 1, 'Golden Triangle Tours 4 Days', 'golden-triangle-tours-4-days', 'Explore Delhi, Agra & Jaipur on a 4-day Golden Triangle tour featuring the iconic Taj Mahal and royal heritage sites.', 'Embark on a captivating journey through India\'s iconic Golden Triangle in just 4 days. This tour covers the historic cities of Delhi, Agra, and Jaipur, offering a perfect blend of culture, heritage, and architecture.', 4, 3, '0.00', NULL, 'per_person', '695f41e825ed9_1767850472.jpg', NULL, NULL, 20, 0, 'easy', '', '', '4 Days Golden Triangle Tour with Taj Mahal , Delhi Agra Jaipur Golden Triangle Tour – 4 Days', '4 Days Golden Triangle Tour with Taj Mahal , Delhi Agra Jaipur Golden Triangle Tour – 4 Days', '4 Days Golden Triangle Tour with Taj Mahal , Delhi Agra Jaipur Golden Triangle Tour – 4 Days', 1, 0, 0, 0, 61, '2026-01-03 06:59:22', '2026-01-29 08:29:57'),
(39, 1, 'Golden Triangle Tour with Udaipur', 'golden-triangle-tour-with-udaipur', 'A 6–8 day Golden Triangle tour that blends the heritage of Delhi, Agra & Jaipur with the lake city charm of Udaipur.', 'Explore India’s Golden Triangle with this 6–8 day package covering Delhi, Agra, Jaipur and beautiful Udaipur. Visit iconic landmarks like the Taj Mahal, Agra Fort, Amber Fort, City Palace and enjoy the scenic lakes and palaces of Udaipur.', 8, 7, '25500.00', NULL, 'per_person', '695f419773cb6_1767850391.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Golden Triangle tour, Udaipur tour package, Delhi Agra Jaipur Udaipur, India Golden Triangle, Udaipur travel', '', 'Golden Triangle tour, Udaipur tour package, Delhi Agra Jaipur Udaipur, India Golden Triangle, Udaipur travel', 1, 0, 0, 0, 55, '2026-01-03 07:14:30', '2026-01-30 00:13:12'),
(40, 1, 'Golden Triangle Tour with Ranthambore', 'golden-triangle-tour-with-ranthambore', 'A heritage and wildlife adventure combining the Golden Triangle with an exciting Ranthambore safari.', 'Explore the best of India’s Golden Triangle with this exciting tour to Delhi, Agra, Jaipur and Ranthambore. Visit iconic sites like the Taj Mahal, Agra Fort, Amber Fort, and enjoy thrilling wildlife safari at Ranthambore National Park.', 7, 6, '0.00', NULL, 'per_person', '695f413d91d6d_1767850301.jpg', NULL, NULL, 20, 0, 'easy', '', '', 'Golden Triangle with Ranthambore Tour | Delhi Agra Jaipur Ranthambore Package | Ranthambore, Tour Package', 'Explore the best of India’s Golden Triangle with this exciting tour to Delhi, Agra, Jaipur and Ranthambore. Visit iconic sites like the Taj Mahal, Agra Fort, Amber Fort, and enjoy thrilling wildlife safari at Ranthambore National Park.', 'Golden Triangle tour, Ranthambore safari, Delhi Agra Jaipur Ranthambore, Taj Mahal tour package, India wildlife tour', 1, 1, 0, 0, 60, '2026-01-03 07:35:02', '2026-01-29 23:23:18'),
