(79, 16, '11 Nights 12 Days Rajasthan Village & Wildlife Photography Tour', '11-nights-12-days-rajasthan-village-wildlife-photography-tour', 'A photography-focused journey capturing rural life, wildlife, and landscapes across Rajasthan.', 'The Rajasthan Village & Wildlife Photography Tour is designed for photography enthusiasts seeking authentic rural scenes and wildlife encounters. Explore traditional villages, colorful markets, desert landscapes, and renowned wildlife sanctuaries. Capture portraits of local life, cultural traditions, and natural beauty while experiencing Rajasthan’s rich heritage and biodiversity.', 12, 11, '0.00', NULL, 'per_person', '69748bbfcd523_1769245631.jpg', NULL, NULL, 20, 0, 'easy', '', '', '11 Nights 12 Days Rajasthan Village & Wildlife Photography Tour, Rajasthan Village Tour', 'Join the 11 Nights 12 Days Rajasthan Village & Wildlife Photography Tour to capture rural life, desert landscapes, wildlife, and vibrant local culture.', 'Rajasthan photography tour, Rajasthan village tour, wildlife photography India, Rajasthan wildlife tour, photography holiday India', 1, 0, 0, 0, 29, '2026-01-24 09:07:11', '2026-01-29 21:56:14'),
(80, 16, '13 Nights 14 Days Textile Tour Of India', '13-nights-14-days-textile-tour-of-india', 'Explore India’s rich textile heritage through traditional weaving, dyeing, and craftsmanship centers.', 'The Textile Tour of India offers a deep insight into India’s centuries-old textile traditions. Visit weaving villages, artisan workshops, and textile hubs known for handloom, embroidery, block printing, and natural dyes. Interact with craftsmen and discover the cultural stories behind India’s world-famous fabrics and designs.', 14, 13, '0.00', NULL, 'per_person', '69748d17b9983_1769245975.jpg', NULL, NULL, 20, 0, 'easy', '', '', '13 Nights 14 Days Textile Tour Of India, Textile Tour of India, 14 Days India Tour', 'Discover India’s textile heritage on the 13 Nights 14 Days Textile Tour of India, featuring weaving villages, artisan workshops, and traditional crafts.', 'Textile tour of India, Indian handloom tour, textile heritage India, craft tour India, textile travel India', 1, 0, 0, 0, 24, '2026-01-24 09:12:55', '2026-01-29 11:55:51'),
(81, 16, '13 Nights 14 Days Museum Tour Of India', '13-nights-14-days-museum-tour-of-india', 'A cultural journey exploring India’s most important museums and historical collections.', 'The Museum Tour of India is perfect for history and culture lovers. Visit renowned museums showcasing ancient sculptures, royal artifacts, paintings, textiles, and archaeological treasures. This tour provides deep insights into India’s art, history, civilization, and cultural evolution through curated museum experiences.', 14, 13, '0.00', NULL, 'per_person', '69748e220c7bd_1769246242.jpg', NULL, NULL, 20, 0, 'easy', '', '', '13 Nights 14 Days Museum Tour Of India, Heritage India Tour, Museum Tour of India, 14 Days Art & Heritage Trip', 'Explore India’s rich history and culture on the 13 Nights 14 Days Museum Tour of India, featuring iconic museums and historical collections.', 'Museum tour of India, India cultural tour, heritage museums India, history tour India, art museum tour India', 1, 0, 0, 0, 24, '2026-01-24 09:17:22', '2026-01-29 08:08:21'),
(82, 16, '14 Nights 15 Days Village Tour Of Rajasthan', '14-nights-15-days-village-tour-of-rajasthan', 'Experience authentic rural life, traditions, and culture on this immersive Rajasthan village tour.', 'The Village Tour of Rajasthan takes you beyond popular tourist spots into the heart of rural Rajasthan. Experience traditional village life, folk music, crafts, farming practices, and warm local hospitality. This tour offers a deeper cultural connection while showcasing desert landscapes, heritage homes, and timeless traditions.', 15, 14, '0.00', NULL, 'per_person', '697490bf8c066_1769246911.jpg', NULL, NULL, 20, 0, 'easy', '', '', '14 Nights 15 Days Rajasthan Village Tour, Rajasthan Village Tour, Village Tour of Rajasthan', 'Experience authentic rural life on the 14 Nights 15 Days Village Tour of Rajasthan, featuring village stays, traditions, crafts, and cultural experiences.', 'Rajasthan village tour, rural Rajasthan tour, cultural village tour India, traditional Rajasthan tour, offbeat Rajasthan travel', 1, 0, 0, 0, 23, '2026-01-24 09:28:31', '2026-01-30 02:58:06'),
(83, 16, '15 Nights 16 Days Culinary Tour Of India', '15-nights-16-days-culinary-tour-of-india', 'Taste India’s diverse regional cuisines on this immersive culinary journey across the country.', 'The Culinary Tour of India is a food lover’s dream, offering hands-on cooking experiences, market visits, and tastings of regional specialties. Explore diverse flavors from different states, learn traditional cooking techniques, and discover the cultural stories behind India’s rich and varied cuisine.', 16, 15, '0.00', NULL, 'per_person', '697491e1ed1cb_1769247201.jpg', NULL, NULL, 20, 0, 'easy', '', '', '15 Nights 16 Days Culinary Tour Of India, Indian Food Tour', 'Explore India through its flavors on the 15 Nights 16 Days Culinary Tour of India, featuring regional cuisines, cooking experiences, and food culture.', 'Culinary tour of India, food tour India, Indian cuisine tour, cooking tour India, gastronomic tour India', 1, 0, 0, 0, 21, '2026-01-24 09:33:21', '2026-01-30 00:37:50');
